import subprocess, sys, time, re, os
def sh(*a):
    return subprocess.run(["tmux"]+list(a), capture_output=True, text=True).stdout
def start(name, cmd, w=100, h=30):
    subprocess.run(["tmux","kill-session","-t",name], capture_output=True)
    subprocess.run(["tmux","new-session","-d","-s",name,"-x",str(w),"-y",str(h), cmd])
def keys(name, *k):
    subprocess.run(["tmux","send-keys","-t",name]+list(k))
def lit(name, s):
    subprocess.run(["tmux","send-keys","-t",name,"-l",s])
SGR = re.compile(r'\x1b\[([0-9;]*)m')
def parse_line(line):
    # returns text, list of (col, style)
    st = {}
    out = []
    styles = []
    pos = 0
    i = 0
    while i < len(line):
        m = SGR.match(line, i)
        if m:
            codes = m.group(1).split(';') if m.group(1) else ['0']
            j = 0
            while j < len(codes):
                c = codes[j]
                if c in ('0',''): st = {}
                elif c == '38' and codes[j+1]=='5': st['fg']=codes[j+2]; j+=2
                elif c == '48' and codes[j+1]=='5': st['bg']=codes[j+2]; j+=2
                elif c == '38' and codes[j+1]=='2': st['fg']='#'+'/'.join(codes[j+2:j+5]); j+=4
                elif c == '48' and codes[j+1]=='2': st['bg']='#'+'/'.join(codes[j+2:j+5]); j+=4
                elif c == '39': st.pop('fg',None)
                elif c == '49': st.pop('bg',None)
                elif 30<=int(c)<=37: st['fg']=str(int(c)-30)
                elif 40<=int(c)<=47: st['bg']=str(int(c)-40)
                elif 90<=int(c)<=97: st['fg']=str(int(c)-90+8)
                elif 100<=int(c)<=107: st['bg']=str(int(c)-100+8)
                elif c=='1': st['b']=1
                elif c=='2': st['dim']=1
                elif c=='3': st['i']=1
                elif c=='4': st['u']=1
                elif c=='7': st['rev']=1
                elif c=='22': st.pop('b',None); st.pop('dim',None)
                elif c=='23': st.pop('i',None)
                elif c=='24': st.pop('u',None)
                elif c=='27': st.pop('rev',None)
                else: st['?'+c]=1
                j+=1
            i = m.end(); continue
        out.append(line[i]); styles.append(tuple(sorted(st.items()))); i+=1
    return ''.join(out), styles
def cap(name, styles=True):
    raw = sh("capture-pane","-p","-e","-t",name)
    plain = sh("capture-pane","-p","-t",name)
    res = []
    for n,l in enumerate(plain.split('\n')[:-1]):
        res.append("%2d|%s" % (n, l))
    if styles:
        res.append("--styles--")
        for n,l in enumerate(raw.split('\n')[:-1]):
            t, s = parse_line(l)
            runs = []
            cur = None; startc = 0
            for c,(ch,stt) in enumerate(zip(t,s)):
                if stt != cur:
                    if cur: runs.append((startc, c-1, cur, t[startc:c]))
                    cur = stt; startc = c
            if cur: runs.append((startc, len(t)-1, cur, t[startc:]))
            if runs:
                res.append("%2d: " % n + "  ".join("[%d-%d %s %r]" % (a,b,','.join('%s=%s'%kv for kv in st), txt[:30]) for a,b,st,txt in runs))
    cur = sh("display-message","-p","-t",name,"#{cursor_x},#{cursor_y} vis=#{cursor_flag}")
    res.append("cursor: "+cur.strip())
    return '\n'.join(res)
if __name__ == '__main__':
    pass
