fn in_table(c: u32, table: &[(u32, u32)]) -> bool {
    let mut lo = 0usize;
    let mut hi = table.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = table[mid];
        if c < a {
            hi = mid;
        } else if c > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

pub fn is_control(c: char) -> bool {
    let u = c as u32;
    u < 0x20 || (0x7f..0xa0).contains(&u)
}

/// Width of a char as used inside a string (control chars count as 1).
pub fn char_width(c: char) -> usize {
    let u = c as u32;
    if is_control(c) {
        return 1;
    }
    if u < 0x300 {
        return 1;
    }
    if in_table(u, ZERO) {
        return 0;
    }
    if in_table(u, WIDE) {
        return 2;
    }
    1
}

pub fn is_extend(c: char) -> bool {
    let u = c as u32;
    if u < 0x300 {
        return false;
    }
    if u == 0x200D {
        return true;
    }
    if (0x1F3FB..=0x1F3FF).contains(&u) {
        return true;
    }
    in_table(u, ZERO) && !(0x200B..=0x200C).contains(&u) && !(0x202A..=0x202E).contains(&u) && !(0x2060..=0x2064).contains(&u) && u != 0xFEFF
}

pub fn str_width(s: &str) -> usize {
    graphemes(s).map(grapheme_width).sum()
}

pub fn grapheme_width(g: &str) -> usize {
    match g.chars().next() {
        Some(c) => char_width(c),
        None => 0,
    }
}

pub struct Graphemes<'a> {
    s: &'a str,
    pos: usize,
}

