pub const RATATUI_BUFFER_LOC: &str =
    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/ratatui-0.29.0/src/buffer/buffer.rs:253:13";

/// Emulates the panic hook installed while the TUI is active.
pub fn tui_panic(location: &str, msg: &str) -> ! {
    // leave alternate screen on stdout, restore terminal, report on stderr
    let mut out = std::io::stdout();
    let _ = out.write_all(b"\x1b[?1049l");
    let _ = out.flush();
    crate::term::disable_raw_mode();
    let mut err = std::io::stderr();
    let _ = write!(err, "\x1b[?1049lpanicked at {}:\n{}\n", location, msg);
    let _ = err.flush();
    std::process::exit(1);
}

/// Emulates a default rust panic (outside of the tui)
pub fn plain_panic(location: &str, msg: &str) -> ! {
    let mut err = std::io::stderr();
    let tid = std::process::id();
    let _ = write!(
        err,
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        tid, location, msg
    );
    let _ = err.flush();
    std::process::exit(101);
}

/// Format a string slice error message like rust's core does for `&s[..end]`.
pub fn slice_end_error(s: &str, end: usize) -> String {
    let (trunc, ellipsis) = truncate_to_char_boundary(s, 256);
    if end > s.len() {
        return format!("byte index {} is out of bounds of `{}`{}", end, trunc, ellipsis);
    }
    // not a char boundary
    let mut char_start = end;
    while !s.is_char_boundary(char_start) {
        char_start -= 1;
    }
    let ch = s[char_start..].chars().next().unwrap();
    let char_range = char_start..char_start + ch.len_utf8();
    format!(
        "byte index {} is not a char boundary; it is inside {:?} (bytes {:?}) of `{}`{}",
        end, ch, char_range, trunc, ellipsis
    )
}

fn truncate_to_char_boundary(s: &str, mut max: usize) -> (&str, &str) {
    if max >= s.len() {
        (s, "")
    } else {
        while !s.is_char_boundary(max) {
            max -= 1;
        }
        (&s[..max], "[...]")
    }
}
