#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add: u16,
    pub sub: u16,
}

impl Style {
    pub fn fg(c: Color) -> Style {
        Style { fg: Some(c), ..Default::default() }
    }
    pub fn fg_bg(f: Color, b: Color) -> Style {
        Style { fg: Some(f), bg: Some(b), ..Default::default() }
    }
    pub fn patch(self, other: Style) -> Style {
        Style {
            fg: other.fg.or(self.fg),
            bg: other.bg.or(self.bg),
            add: (self.add & !other.sub) | other.add,
            sub: (self.sub & !other.add) | other.sub,
        }
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: u16,
    pub skip: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Cell { symbol: " ".to_string(), fg: Color::Reset, bg: Color::Reset, modifier: 0, skip: false }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Self {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn append_symbol(&mut self, s: &str) -> &mut Self {
        self.symbol.push_str(s);
        self
    }
    pub fn set_style(&mut self, style: Style) -> &mut Self {
        if let Some(c) = style.fg {
            self.fg = c;
        }
        if let Some(c) = style.bg {
            self.bg = c;
        }
        self.modifier |= style.add;
        self.modifier &= !style.sub;
        self
    }
    pub fn reset(&mut self) {
        *self = Cell::default();
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Rect {
        let max_w = u16::MAX - x;
        let max_h = u16::MAX - y;
        Rect { x, y, width: width.min(max_w), height: height.min(max_h) }
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }
    pub fn intersection(&self, other: Rect) -> Rect {
        let x1 = self.x.max(other.x);
        let y1 = self.y.max(other.y);
        let x2 = self.right().min(other.right());
        let y2 = self.bottom().min(other.bottom());
        Rect { x: x1, y: y1, width: x2.saturating_sub(x1), height: y2.saturating_sub(y1) }
    }
    pub fn indent_x(&self, offset: u16) -> Rect {
        Rect { x: self.x.saturating_add(offset), width: self.width.saturating_sub(offset), ..*self }
