    fn tcgetattr(fd: c_int, t: *mut Termios) -> c_int;
    fn tcsetattr(fd: c_int, act: c_int, t: *const Termios) -> c_int;
    fn cfmakeraw(t: *mut Termios);
    fn ioctl(fd: c_int, req: c_ulong, ...) -> c_int;
    fn isatty(fd: c_int) -> c_int;
    fn open(path: *const i8, flags: c_int, ...) -> c_int;
    fn close(fd: c_int) -> c_int;
    fn read(fd: c_int, buf: *mut c_void, n: usize) -> isize;
    fn write(fd: c_int, buf: *const c_void, n: usize) -> isize;
    fn poll(fds: *mut PollFd, n: c_ulong, timeout: c_int) -> c_int;
    fn pipe(fds: *mut c_int) -> c_int;
}

const TIOCGWINSZ: c_ulong = 0x5413;
const O_RDWR: c_int = 2;
pub const POLLIN: i16 = 1;

struct RawState {
    fd: c_int,
    close_fd: bool,
    orig: Termios,
}

static RAW: Mutex<Option<RawState>> = Mutex::new(None);

pub fn is_tty(fd: c_int) -> bool {
    unsafe { isatty(fd) == 1 }
}

fn open_dev_tty() -> io::Result<c_int> {
    let path = b"/dev/tty\0";
    let fd = unsafe { open(path.as_ptr() as *const i8, O_RDWR) };
    if fd < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(fd)
    }
}

/// fd used for reading input (stdin if it's a tty, /dev/tty otherwise)
pub fn tty_fd() -> io::Result<(c_int, bool)> {
    if is_tty(0) {
        Ok((0, false))
    } else {
        Ok((open_dev_tty()?, true))
    }
}

pub fn enable_raw_mode() -> io::Result<()> {
    let mut g = RAW.lock().unwrap();
    if g.is_some() {
        return Ok(());
    }
    let (fd, close_fd) = tty_fd()?;
    let mut t: Termios = unsafe { std::mem::zeroed() };
    if unsafe { tcgetattr(fd, &mut t) } != 0 {
        let e = io::Error::last_os_error();
        if close_fd {
            unsafe { close(fd) };
        }
        return Err(e);
    }
    let orig = t;
    unsafe { cfmakeraw(&mut t) };
    if unsafe { tcsetattr(fd, 0, &t) } != 0 {
        let e = io::Error::last_os_error();
        if close_fd {
            unsafe { close(fd) };
        }
        return Err(e);
    }
    *g = Some(RawState { fd, close_fd, orig });
    Ok(())
}

pub fn disable_raw_mode() {
    let mut g = match RAW.lock() {
        Ok(g) => g,
        Err(p) => p.into_inner(),
    };
    if let Some(st) = g.take() {
        unsafe {
            tcsetattr(st.fd, 0, &st.orig);
            if st.close_fd {
                close(st.fd);
            }
        }
    }
}

pub fn terminal_size() -> (u16, u16) {
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let tty = open_dev_tty();
    let fd = match tty {
        Ok(fd) => fd,
        Err(_) => 1,
    };
    let r = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if let Ok(fd) = tty {
        unsafe { close(fd) };
    }
    if r == 0 {
        (ws.ws_col, ws.ws_row)
    } else {
        (80, 24)
    }
}

pub fn poll_fds(fds: &mut [PollFd], timeout_ms: i32) -> i32 {
    unsafe { poll(fds.as_mut_ptr(), fds.len() as c_ulong, timeout_ms) }
}

pub fn read_fd(fd: c_int, buf: &mut [u8]) -> isize {
    unsafe { read(fd, buf.as_mut_ptr() as *mut c_void, buf.len()) }
}

pub fn write_fd(fd: c_int, buf: &[u8]) -> isize {
    unsafe { write(fd, buf.as_ptr() as *const c_void, buf.len()) }
}

pub fn make_pipe() -> (c_int, c_int) {
    let mut fds = [0 as c_int; 2];
    unsafe { pipe(fds.as_mut_ptr()) };
    (fds[0], fds[1])
}

