use crate::buffer::{Buffer, Rect, Style};
use crate::unicode;

#[derive(Clone, Debug, Default)]
pub struct Span {
    pub content: String,
    pub style: Style,
}

impl Span {
    pub fn raw<S: Into<String>>(s: S) -> Span {
        Span { content: s.into(), style: Style::default() }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Span {
        Span { content: s.into(), style }
    }
    pub fn width(&self) -> usize {
        unicode::str_width(&self.content)
    }
}

#[derive(Clone, Debug, Default)]
pub struct Line {
    pub spans: Vec<Span>,
}

impl Line {
    pub fn raw<S: Into<String>>(s: S) -> Line {
        Line { spans: vec![Span::raw(s)] }
    }
    pub fn from_spans(spans: Vec<Span>) -> Line {
        Line { spans }
    }
    pub fn width(&self) -> usize {
        self.spans.iter().map(|s| s.width()).sum()
    }
}

/// Text from a string, split into lines like ratatui's `Text::from(&str)` (uses `str::lines`).
pub fn text_raw(s: &str) -> Vec<Line> {
    s.lines().map(Line::raw).collect()
}

fn render_span(span: &Span, area: Rect, buf: &mut Buffer) {
    let area = area.intersection(buf.area);
    if area.is_empty() {
        return;
    }
    let mut x = area.x;
    let y = area.y;
    let style = Style::default().patch(span.style);
    for (i, g) in unicode::graphemes(&span.content).enumerate() {
        if g == "\n" {
            continue;
        }
        let w = unicode::grapheme_width(g) as u16;
        let next_x = x.saturating_add(w);
        if next_x > area.right() {
            break;
        }
        if i == 0 {
            buf.cell(x, y).set_symbol(g).set_style(style);
        } else if x == area.x {
            buf.cell(x, y).append_symbol(g).set_style(style);
        } else if w == 0 {
            buf.cell(x - 1, y).append_symbol(g).set_style(style);
        } else {
            buf.cell(x, y).set_symbol(g).set_style(style);
        }
