/// ratatui Line::render (left aligned)
pub fn render_line(line: &Line, area: Rect, buf: &mut Buffer) {
    let area = area.intersection(buf.area);
    if area.is_empty() {
        return;
    }
    let area = Rect { height: 1, ..area };
    let line_width = line.width();
    if line_width == 0 {
        return;
    }
    let mut area = area;
    // spans_after_width with skip 0
    for span in &line.spans {
        let sw = span.width();
        if sw == 0 {
            continue;
        }
        if area.is_empty() {
            break;
        }
        render_span(span, area, buf);
        let sw16: u16 = sw.try_into().unwrap_or(u16::MAX);
        area = area.indent_x(sw16);
    }
}

pub struct Block {
    pub title: Option<Span>,
}

impl Block {
    pub fn new(title: Option<Span>) -> Block {
        Block { title }
    }
    pub fn inner(&self, area: Rect) -> Rect {
        let mut inner = area;
        inner.x = inner.x.saturating_add(1).min(inner.right());
        inner.width = inner.width.saturating_sub(1);
        inner.y = inner.y.saturating_add(1).min(inner.bottom());
        inner.height = inner.height.saturating_sub(1);
        inner.width = inner.width.saturating_sub(1);
        inner.height = inner.height.saturating_sub(1);
        inner
    }
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        if area.is_empty() {
            return;
        }
        // borders
        for y in area.y..area.bottom() {
            buf.cell(area.x, y).set_symbol("│");
        }
        for x in area.x..area.right() {
            buf.cell(x, area.y).set_symbol("─");
        }
        let r = area.right() - 1;
        for y in area.y..area.bottom() {
            buf.cell(r, y).set_symbol("│");
        }
        let b = area.bottom() - 1;
        for x in area.x..area.right() {
            buf.cell(x, b).set_symbol("─");
        }
        buf.cell(r, b).set_symbol("┘");
        buf.cell(r, area.y).set_symbol("┐");
        buf.cell(area.x, b).set_symbol("└");
        buf.cell(area.x, area.y).set_symbol("┌");
        // title
        if let Some(t) = &self.title {
            let titles_area = Rect { x: area.x + 1, y: area.y, width: area.width.saturating_sub(2), height: 1 };
            if !titles_area.is_empty() {
                let tw = t.width() as u16;
                let title_area = Rect { width: tw.min(titles_area.width), ..titles_area };
                let line = Line { spans: vec![t.clone()] };
                render_line(&line, title_area, buf);
            }
        }
    }
}

/// ratatui Paragraph without wrapping.
pub fn render_paragraph(lines: &[Line], block: Option<&Block>, area: Rect, buf: &mut Buffer) {
    let text_area = match block {
        Some(b) => {
            b.render(area, buf);
            b.inner(area)
        }
        None => area,
    };
    if text_area.is_empty() {
        return;
    }
    let max_w = text_area.width;
    let mut y: u16 = 0;
    for line in lines {
        // LineTruncator
        let mut cur: Vec<(&str, Style)> = Vec::new();
        let mut cur_w: u16 = 0;
        'outer: for span in &line.spans {
            let style = Style::default().patch(span.style);
            for g in unicode::graphemes(&span.content) {
                if g == "\n" {
                    continue;
                }
                let w = unicode::grapheme_width(g) as u16;
                if w > max_w {
                    continue;
                }
                if cur_w + w > max_w {
                    break 'outer;
                }
                cur_w += w;
                cur.push((g, style));
            }
        }
        let mut x: u16 = 0;
        for (g, style) in cur {
            let w = unicode::grapheme_width(g) as u16;
            if w == 0 {
                continue;
            }
            let sym = if g.is_empty() { " " } else { g };
            let cx = text_area.x.wrapping_add(x);
            let cy = text_area.y.wrapping_add(y);
            buf.cell(cx, cy).set_symbol(sym).set_style(style);
            x += w;
        }
        y += 1;
        if y >= text_area.height {
            break;
        }
    }
}

/// ratatui List widget (top to bottom, offset always 0 at start of render).
pub fn render_list(
    items: &[Line],
    block: &Block,
    area: Rect,
    buf: &mut Buffer,
    selected: Option<usize>,
    highlight_symbol: Option<&str>,
    highlight_style: Style,
) {
    block.render(area, buf);
    let list_area = block.inner(area);
    if list_area.is_empty() {
        return;
    }
    if items.is_empty() {
        return;
    }
    let mut selected = selected;
    if let Some(s) = selected {
        if s >= items.len() {
            selected = Some(items.len() - 1);
        }
    }
    let max_height = list_area.height as usize;
    // get_items_bounds with offset 0 and item heights 1
    let offset = 0usize;
    let mut first = offset;
    let mut last = offset;
    let mut height_from_offset = 0usize;
    for _ in items.iter().skip(offset) {
        if height_from_offset + 1 > max_height {
            break;
        }
        height_from_offset += 1;
        last += 1;
    }
    let index_to_display = selected.unwrap_or(offset);
    while index_to_display >= last {
        height_from_offset += 1;
        last += 1;
        while height_from_offset > max_height {
            height_from_offset -= 1;
            first += 1;
        }
    }
    let hs = highlight_symbol.unwrap_or("");
    let hs_w = unicode::str_width(hs);
    let blank = " ".repeat(hs_w);
    let selection_spacing = highlight_symbol.is_some() && selected.is_some();
    let mut current_height = 0u16;
    for (i, item) in items.iter().enumerate().skip(first).take(last - first) {
        let x = list_area.x;
        let y = list_area.y + current_height;
        current_height += 1;
        let row_area = Rect { x, y, width: list_area.width, height: 1 };
        let is_selected = selected == Some(i);
        let item_area = if selection_spacing {
            Rect { x: row_area.x + hs_w as u16, width: row_area.width.saturating_sub(hs_w as u16), ..row_area }
        } else {
            row_area
        };
        render_line(item, item_area, buf);
        if selection_spacing {
            let sym = if is_selected { hs } else { &blank };
            buf.set_stringn(x, y, sym, list_area.width as usize, Style::default());
        }
        if is_selected {
            buf.set_style(row_area, highlight_style);
        }
    }
}
