fn parse_u8(s: &[u8], i: usize) -> Option<(u8, usize)> {
    let mut j = i;
    let mut v: u32 = 0;
    while j < s.len() && s[j].is_ascii_digit() {
        v = v * 10 + (s[j] - b'0') as u32;
        if v > 255 {
            return None;
        }
        j += 1;
    }
    if j == i {
        return None;
    }
    Some((v as u8, j))
}

enum Item {
    Code(u8),
    Fg(Color),
    Bg(Color),
}

fn parse_color(s: &[u8], i: usize) -> Option<(Color, usize)> {
    let (t, mut j) = parse_u8(s, i)?;
    match t {
        2 | 5 => {}
        _ => return None,
    }
    if j < s.len() && s[j] == b';' {
        j += 1;
    }
    if t == 2 {
        let (r, j1) = parse_u8(s, j)?;
        if s.get(j1) != Some(&b';') {
            return None;
        }
        let (g, j2) = parse_u8(s, j1 + 1)?;
        if s.get(j2) != Some(&b';') {
            return None;
        }
        let (b, j3) = parse_u8(s, j2 + 1)?;
        Some((Color::Rgb(r, g, b), j3))
    } else {
        let (n, j1) = parse_u8(s, j)?;
        Some((Color::Indexed(n), j1))
    }
}

fn parse_item(s: &[u8], i: usize) -> Option<(Item, usize)> {
    let (c, mut j) = parse_u8(s, i)?;
    let item = if c == 38 || c == 48 {
        if j < s.len() && s[j] == b';' {
            j += 1;
        }
        let (col, j2) = parse_color(s, j)?;
        j = j2;
        if c == 38 {
            Item::Fg(col)
        } else {
            Item::Bg(col)
        }
    } else {
        Item::Code(c)
    };
    if j < s.len() && s[j] == b';' {
        j += 1;
    }
    Some((item, j))
}

/// Try parsing an SGR sequence at s[i] (which is ESC). Returns (items, next index).
fn parse_sgr(s: &[u8], i: usize) -> Option<(Vec<Item>, usize)> {
    if s.get(i) != Some(&0x1b) || s.get(i + 1) != Some(&b'[') {
        return None;
    }
    let mut j = i + 2;
    let mut items = Vec::new();
    while let Some((it, nj)) = parse_item(s, j) {
        items.push(it);
        j = nj;
    }
    if s.get(j) == Some(&b'm') {
        Some((items, j + 1))
    } else {
        None
    }
}

/// Skip any escape sequence at s[i] (ESC).
fn skip_escape(s: &[u8], i: usize) -> usize {
    let mut j = i + 1;
    match s.get(j) {
        Some(b'[') => {
            j += 1;
            while j < s.len() && !s[j].is_ascii_alphabetic() {
                j += 1;
            }
            if j < s.len() {
                j += 1;
            }
            j
        }
        Some(b']') => {
            j += 1;
            while j < s.len() && s[j] != 0x07 {
                j += 1;
            }
            if j < s.len() {
                j += 1;
            }
            j
        }
        _ => j,
    }
}

fn apply_items(style: Style, items: &[Item]) -> Style {
    use modifier::*;
    let mut st = style;
    if items.is_empty() {
        st = style_reset();
    }
    for it in items {
        match it {
            Item::Fg(c) => st.fg = Some(*c),
            Item::Bg(c) => st.bg = Some(*c),
            Item::Code(c) => match c {
                0 => st = style_reset(),
                1 => st = add_mod(st, BOLD),
                2 => st = add_mod(st, DIM),
                3 => st = add_mod(st, ITALIC),
                4 => st = add_mod(st, UNDERLINED),
                5 => st = add_mod(st, SLOW_BLINK),
                6 => st = add_mod(st, RAPID_BLINK),
                7 => st = add_mod(st, REVERSED),
                8 => st = add_mod(st, HIDDEN),
                9 => st = add_mod(st, CROSSED_OUT),
                22 => st = rem_mod(rem_mod(st, BOLD), DIM),
                30..=37 => st.fg = Some(Color::Indexed(c - 30)),
                39 => st.fg = Some(Color::Reset),
                40..=47 => st.bg = Some(Color::Indexed(c - 40)),
                49 => st.bg = Some(Color::Reset),
                90..=97 => st.fg = Some(Color::Indexed(c - 90 + 8)),
                100..=106 => st.bg = Some(Color::Indexed(c - 100 + 8)),
                107 => st.fg = Some(Color::Indexed(15)),
                _ => {}
            },
        }
    }
    st
}

pub fn parse(text: &str) -> Vec<Line> {
    let s = text.as_bytes();
    let mut lines = Vec::new();
    let mut last = Style::default();
    let mut pos = 0;
    loop {
        // one line
        let mut end = pos;
        while end < s.len() && s[end] != b'\n' {
            end += 1;
        }
        let line_bytes = &s[pos..end];
        let mut next = end;
        if next < s.len() {
            next += 1; // consume newline
        }
        let mut spans = Vec::new();
        let mut i = 0;
        while i < line_bytes.len() {
            let mut st = last;
            if line_bytes[i] == 0x1b {
                if let Some((items, ni)) = parse_sgr(line_bytes, i) {
                    st = apply_items(last, &items);
                    i = ni;
                } else {
                    i = skip_escape(line_bytes, i);
                }
            }
            let start = i;
            while i < line_bytes.len() && line_bytes[i] != 0x1b {
                i += 1;
            }
            let content = String::from_utf8_lossy(&line_bytes[start..i]).to_string();
            last = last.patch(st);
            if !content.is_empty() {
                spans.push(Span::styled(content, st));
            }
        }
        lines.push(Line::from_spans(spans));
        pos = next;
        if pos >= s.len() {
            break;
        }
    }
    lines
}
