pub struct TomlError {
    pub pos: usize,
    pub message: String,
}

pub fn format_error(raw: &str, e: &TomlError) -> String {
    let input = raw.as_bytes();
    let (line, column) = translate_position(input, e.pos);
    let line_num = line + 1;
    let col_num = column + 1;
    let gutter = line_num.to_string().len();
    let content = raw.split('\n').nth(line).unwrap_or("");
    let mut f = String::new();
    f.push_str(&format!("TOML parse error at line {}, column {}\n", line_num, col_num));
    for _ in 0..=gutter {
        f.push(' ');
    }
    f.push_str("|\n");
    f.push_str(&format!("{} | {}\n", line_num, content));
    for _ in 0..=gutter {
        f.push(' ');
    }
    f.push('|');
    for _ in 0..=column {
        f.push(' ');
    }
    f.push('^');
    f.push('\n');
    f.push_str(&e.message);
    f.push('\n');
    f
}

fn translate_position(input: &[u8], index: usize) -> (usize, usize) {
    if input.is_empty() {
        return (0, index);
    }
    let safe_index = index.min(input.len() - 1);
    let column_offset = index - safe_index;
    let index = safe_index;
    let nl = input[0..index].iter().rev().enumerate().find(|(_, b)| **b == b'\n').map(|(nl, _)| index - nl - 1);
    let line_start = match nl {
        Some(nl) => nl + 1,
        None => 0,
    };
    let line = input[0..line_start].iter().filter(|b| **b == b'\n').count();
    let column = std::str::from_utf8(&input[line_start..=index])
        .map(|s| s.chars().count() - 1)
        .unwrap_or_else(|_| index - line_start);
    (line, column + column_offset)
}

struct P<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
}

type R<T> = Result<T, TomlError>;

fn err<T>(pos: usize, msg: &str) -> R<T> {
    Err(TomlError { pos, message: msg.to_string() })
}

