            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    return Ok(Value::Table(tbl));
                }
                _ => return err(self.i, "invalid inline table\nexpected `}`"),
            }
        }
    }
}

fn get_table_mut<'t>(tbl: &'t mut Vec<(String, Value)>, key: &str) -> Option<&'t mut Value> {
    tbl.iter_mut().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn insert_dotted(tbl: &mut Vec<(String, Value)>, keys: &[String], v: Value, pos: usize, ctx: &str) -> R<()> {
    let mut cur = tbl;
    for k in &keys[..keys.len() - 1] {
        if get_table_mut(cur, k).is_none() {
            cur.push((k.clone(), Value::Table(Vec::new())));
        }
        match get_table_mut(cur, k).unwrap() {
            Value::Table(t) => cur = t,
            _ => return err(pos, &format!("duplicate key `{}` in {}", k, ctx)),
        }
    }
    let last = &keys[keys.len() - 1];
    if get_table_mut(cur, last).is_some() {
        return err(pos, &format!("duplicate key `{}` in {}", last, ctx));
    }
    cur.push((last.clone(), v));
    Ok(())
}

fn navigate<'t>(root: &'t mut Vec<(String, Value)>, path: &[String]) -> Option<&'t mut Vec<(String, Value)>> {
    let mut cur = root;
    for k in path {
        match get_table_mut(cur, k)? {
            Value::Table(t) => cur = t,
            Value::Array(a) => match a.last_mut() {
                Some(Value::Table(t)) => cur = t,
                _ => return None,
            },
            _ => return None,
        }
    }
    Some(cur)
}

pub fn parse(src: &str) -> Result<Vec<(String, Value)>, TomlError> {
    let mut p = P { s: src.as_bytes(), src, i: 0 };
    let mut root: Vec<(String, Value)> = Vec::new();
    let mut cur_path: Vec<String> = Vec::new();
    let mut defined: Vec<Vec<String>> = Vec::new();
    // skip BOM
    if p.starts("\u{feff}") {
        p.i += 3;
    }
    loop {
        p.ws();
        let c = match p.peek() {
            None => break,
            Some(c) => c,
        };
        if c == b'#' {
            p.comment();
        } else if c == b'\n' || c == b'\r' {
            if !p.newline() {
                return err(p.i, "invalid key");
            }
            continue;
        } else if c == b'[' {
            let array = p.at(1) == Some(b'[');
            let hstart = p.i;
            p.i += if array { 2 } else { 1 };
            p.ws();
            let (keys, _) = match p.key() {
                Ok(k) => k,
                Err(e) => {
                    return Err(TomlError { pos: e.pos, message: format!("invalid table header\n{}", e.message) })
                }
            };
            p.ws();
            if array {
                if !p.starts("]]") {
                    return err(p.i, "invalid table header\nexpected `.`, `]]`");
                }
                p.i += 2;
            } else {
                if p.peek() != Some(b']') {
                    return err(p.i, "invalid table header\nexpected `.`, `]`");
                }
                p.i += 1;
            }
            // create
            let parent_path = &keys[..keys.len() - 1];
            let lastk = keys[keys.len() - 1].clone();
            {
                let mut cur = &mut root;
                for k in parent_path {
                    if get_table_mut(cur, k).is_none() {
                        cur.push((k.clone(), Value::Table(Vec::new())));
                    }
                    cur = match get_table_mut(cur, k).unwrap() {
                        Value::Table(t) => t,
                        Value::Array(a) => match a.last_mut() {
                            Some(Value::Table(t)) => t,
                            _ => return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", k)),
                        },
                        _ => return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", k)),
                    };
                }
                if array {
                    match get_table_mut(cur, &lastk) {
                        None => cur.push((lastk.clone(), Value::Array(vec![Value::Table(Vec::new())]))),
                        Some(Value::Array(a)) => a.push(Value::Table(Vec::new())),
                        Some(_) => {
                            return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk))
                        }
                    }
                } else {
                    if defined.iter().any(|d| d == &keys) {
                        return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk));
                    }
                    match get_table_mut(cur, &lastk) {
                        None => cur.push((lastk.clone(), Value::Table(Vec::new()))),
                        Some(Value::Table(_)) => {}
                        Some(_) => {
                            return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk))
                        }
                    }
                    defined.push(keys.clone());
                }
            }
            cur_path = keys;
        } else {
            let (keys, kpos) = p.key()?;
            p.ws();
            if p.peek() != Some(b'=') {
                return err(p.i, "expected `.`, `=`");
            }
            p.i += 1;
            p.ws();
            let v = p.value()?;
            let ctx = if cur_path.is_empty() {
                "document root".to_string()
            } else {
                format!("table `{}`", cur_path.join("."))
            };
            let tbl = match navigate(&mut root, &cur_path) {
                Some(t) => t,
                None => return err(kpos, "invalid key"),
            };
            insert_dotted(tbl, &keys, v, kpos, &ctx)?;
        }
        p.ws();
        p.comment();
        if p.peek().is_none() {
            break;
        }
        if !p.newline() {
            return err(p.i, "expected newline, `#`");
        }
    }
    Ok(root)
}
