// A small TOML parser with toml_edit-like error messages.

#[derive(Clone, Debug)]
pub enum Value {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

pub struct TomlError {
    pub pos: usize,
    pub message: String,
}

pub fn format_error(raw: &str, e: &TomlError) -> String {
    let input = raw.as_bytes();
    let (line, column) = translate_position(input, e.pos);
    let line_num = line + 1;
    let col_num = column + 1;
    let gutter = line_num.to_string().len();
    let content = raw.split('\n').nth(line).unwrap_or("");
    let mut f = String::new();
    f.push_str(&format!("TOML parse error at line {}, column {}\n", line_num, col_num));
    for _ in 0..=gutter {
        f.push(' ');
    }
    f.push_str("|\n");
    f.push_str(&format!("{} | {}\n", line_num, content));
    for _ in 0..=gutter {
        f.push(' ');
    }
    f.push('|');
    for _ in 0..=column {
        f.push(' ');
    }
    f.push('^');
    f.push('\n');
    f.push_str(&e.message);
    f.push('\n');
    f
}

fn translate_position(input: &[u8], index: usize) -> (usize, usize) {
    if input.is_empty() {
        return (0, index);
    }
    let safe_index = index.min(input.len() - 1);
    let column_offset = index - safe_index;
    let index = safe_index;
    let nl = input[0..index].iter().rev().enumerate().find(|(_, b)| **b == b'\n').map(|(nl, _)| index - nl - 1);
    let line_start = match nl {
        Some(nl) => nl + 1,
        None => 0,
    };
    let line = input[0..line_start].iter().filter(|b| **b == b'\n').count();
    let column = std::str::from_utf8(&input[line_start..=index])
        .map(|s| s.chars().count() - 1)
        .unwrap_or_else(|_| index - line_start);
    (line, column + column_offset)
}

struct P<'a> {
    s: &'a [u8],
    src: &'a str,
    i: usize,
}

type R<T> = Result<T, TomlError>;

fn err<T>(pos: usize, msg: &str) -> R<T> {
    Err(TomlError { pos, message: msg.to_string() })
}

fn is_bare(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

impl<'a> P<'a> {
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn at(&self, k: usize) -> Option<u8> {
        self.s.get(self.i + k).copied()
    }
    fn starts(&self, t: &str) -> bool {
        self.s[self.i..].starts_with(t.as_bytes())
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn comment(&mut self) {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                self.i += 1;
            }
        }
    }
    fn newline(&mut self) -> bool {
        match self.peek() {
            Some(b'\n') => {
                self.i += 1;
                true
            }
            Some(b'\r') if self.at(1) == Some(b'\n') => {
                self.i += 2;
                true
            }
            _ => false,
        }
    }
    fn ws_comment_newline(&mut self) {
        loop {
            self.ws();
            self.comment();
            if !self.newline() {
                break;
            }
        }
    }
    fn simple_key(&mut self) -> R<String> {
        match self.peek() {
            Some(b'"') => {
                if self.starts("\"\"\"") {
                    return err(self.i, "invalid key");
                }
                self.basic_string()
            }
            Some(b'\'') => {
                if self.starts("'''") {
                    return err(self.i, "invalid key");
                }
                self.literal_string()
            }
            Some(c) if is_bare(c) => {
                let st = self.i;
                while let Some(c) = self.peek() {
                    if is_bare(c) {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                Ok(self.src[st..self.i].to_string())
            }
            _ => err(self.i, "invalid key"),
        }
    }
    fn key(&mut self) -> R<(Vec<String>, usize)> {
        let start = self.i;
        let mut parts = vec![self.simple_key()?];
        loop {
            let save = self.i;
            self.ws();
            if self.peek() == Some(b'.') {
                self.i += 1;
                self.ws();
                parts.push(self.simple_key()?);
            } else {
                self.i = save;
                break;
            }
        }
        Ok((parts, start))
    }
    fn escape(&mut self, out: &mut String) -> R<()> {
        // at backslash
        let st = self.i;
        self.i += 1;
        let c = match self.peek() {
            Some(c) => c,
            None => return err(self.i, "invalid escape sequence\nexpected `b`, `f`, `n`, `r`, `t`, `u`, `U`, `\\`, `\"`"),
        };
        self.i += 1;
        match c {
            b'b' => out.push('\u{8}'),
            b't' => out.push('\t'),
            b'n' => out.push('\n'),
            b'f' => out.push('\u{c}'),
            b'r' => out.push('\r'),
            b'"' => out.push('"'),
            b'\\' => out.push('\\'),
            b'e' => out.push('\u{1b}'),
            b'u' | b'U' => {
                let n = if c == b'u' { 4 } else { 8 };
                if self.i + n > self.s.len() {
                    return err(self.i, "invalid unicode 4-digit hex code");
                }
                let hex = &self.src[self.i..self.i + n];
                match u32::from_str_radix(hex, 16).ok().and_then(char::from_u32) {
                    Some(ch) => out.push(ch),
                    None => return err(self.i, "invalid unicode 4-digit hex code"),
                }
                self.i += n;
            }
            _ => {
                let _ = st;
                return err(self.i - 1, "invalid escape sequence\nexpected `b`, `f`, `n`, `r`, `t`, `u`, `U`, `\\`, `\"`");
            }
        }
        Ok(())
    }
    fn basic_string(&mut self) -> R<String> {
        self.i += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None | Some(b'\n') => return err(self.i, "invalid basic string"),
                Some(b'\r') if self.at(1) == Some(b'\n') => return err(self.i, "invalid basic string"),
                Some(b'"') => {
                    self.i += 1;
                    return Ok(out);
                }
                Some(b'\\') => self.escape(&mut out)?,
                Some(_) => {
                    let ch = self.src[self.i..].chars().next().unwrap();
                    out.push(ch);
                    self.i += ch.len_utf8();
                }
            }
        }
    }
    fn literal_string(&mut self) -> R<String> {
        self.i += 1;
        let st = self.i;
        loop {
            match self.peek() {
                None | Some(b'\n') => return err(self.i, "invalid literal string"),
                Some(b'\'') => {
                    let v = self.src[st..self.i].to_string();
                    self.i += 1;
                    return Ok(v);
                }
                Some(_) => self.i += 1,
            }
        }
    }
    fn ml_basic_string(&mut self) -> R<String> {
        self.i += 3;
        self.newline();
        let mut out = String::new();
        loop {
            if self.starts("\"\"\"") {
                self.i += 3;
                // up to two extra quotes belong to the content
                let mut extra = 0;
                while self.peek() == Some(b'"') && extra < 2 {
                    out.push('"');
                    self.i += 1;
                    extra += 1;
                }
                return Ok(out);
            }
            match self.peek() {
                None => return err(self.i, "invalid multiline basic string"),
                Some(b'\\') => {
                    // line ending backslash
                    let mut j = self.i + 1;
                    while j < self.s.len() && (self.s[j] == b' ' || self.s[j] == b'\t') {
                        j += 1;
                    }
                    if j < self.s.len() && (self.s[j] == b'\n' || (self.s[j] == b'\r' && self.s.get(j + 1) == Some(&b'\n'))) {
                        self.i = j;
                        while let Some(c) = self.peek() {
                            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                                self.i += 1;
                            } else {
                                break;
                            }
                        }
                    } else {
                        self.escape(&mut out)?;
                    }
                }
                Some(_) => {
                    let ch = self.src[self.i..].chars().next().unwrap();
                    out.push(ch);
                    self.i += ch.len_utf8();
                }
            }
        }
    }
    fn ml_literal_string(&mut self) -> R<String> {
        self.i += 3;
        self.newline();
        let st = self.i;
        loop {
            if self.starts("'''") {
                let mut end = self.i;
                self.i += 3;
                let mut extra = 0;
                while self.peek() == Some(b'\'') && extra < 2 {
                    self.i += 1;
                    end += 1;
                    extra += 1;
                }
                return Ok(self.src[st..end].to_string());
            }
            match self.peek() {
                None => return err(self.i, "invalid multiline literal string"),
                Some(_) => self.i += 1,
            }
        }
    }
    fn number_or_date(&mut self) -> R<Value> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' || c == b'+' || c == b'-' || c == b'.' || c == b':' {
                self.i += 1;
            } else if c == b' ' && self.i > st && self.is_date_prefix(st) {
                // date time separated by space
                if self.at(1).map(|d| d.is_ascii_digit()).unwrap_or(false) {
                    self.i += 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        let tok = &self.src[st..self.i];
        if tok.is_empty() {
            return err(st, "invalid string\nexpected `\"`, `'`");
        }
        let b = tok.as_bytes();
        let is_date = (b.len() >= 10 && b[4] == b'-' && b[7] == b'-' && b[..4].iter().all(|c| c.is_ascii_digit()))
            || (b.len() >= 8 && b[2] == b':' && b[5] == b':' && b[..2].iter().all(|c| c.is_ascii_digit()));
        if is_date {
            return Ok(Value::Datetime(tok.to_string()));
        }
        match tok {
            "inf" | "+inf" => return Ok(Value::Float(f64::INFINITY)),
            "-inf" => return Ok(Value::Float(f64::NEG_INFINITY)),
            "nan" | "+nan" | "-nan" => return Ok(Value::Float(f64::NAN)),
            _ => {}
        }
        let clean: String = tok.chars().filter(|&c| c != '_').collect();
        let (neg, body) = if let Some(r) = clean.strip_prefix('-') {
            (true, r.to_string())
        } else if let Some(r) = clean.strip_prefix('+') {
            (false, r.to_string())
        } else {
            (false, clean.clone())
        };
        let radix = if body.starts_with("0x") {
            Some(16)
        } else if body.starts_with("0o") {
            Some(8)
        } else if body.starts_with("0b") {
            Some(2)
        } else {
            None
        };
        if let Some(r) = radix {
            if let Ok(v) = i64::from_str_radix(&body[2..], r) {
                return Ok(Value::Integer(if neg { -v } else { v }));
            }
            return err(st, "invalid integer");
        }
        if body.chars().all(|c| c.is_ascii_digit()) && !body.is_empty() {
            if body.len() > 1 && body.starts_with('0') {
                return err(st, "invalid integer");
            }
            if let Ok(v) = clean.parse::<i64>() {
                return Ok(Value::Integer(v));
            }
            return err(st, "invalid integer\nnumber too large to fit in target type");
        }
        if let Ok(v) = clean.parse::<f64>() {
            if body.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                return Ok(Value::Float(v));
            }
        }
        if b[0].is_ascii_digit() || b[0] == b'+' || b[0] == b'-' {
            return err(st, "invalid floating-point number");
        }
        err(st, "invalid string\nexpected `\"`, `'`")
    }
    fn is_date_prefix(&self, st: usize) -> bool {
        let b = &self.s[st..self.i];
        b.len() == 10 && b[4] == b'-' && b[7] == b'-'
    }
    fn value(&mut self) -> R<Value> {
        match self.peek() {
            Some(b'"') => {
                if self.starts("\"\"\"") {
                    Ok(Value::String(self.ml_basic_string()?))
                } else {
                    Ok(Value::String(self.basic_string()?))
                }
            }
            Some(b'\'') => {
                if self.starts("'''") {
                    Ok(Value::String(self.ml_literal_string()?))
                } else {
                    Ok(Value::String(self.literal_string()?))
                }
            }
            Some(b't') if self.starts("true") && !self.at(4).map(is_bare).unwrap_or(false) => {
                self.i += 4;
                Ok(Value::Boolean(true))
            }
            Some(b'f') if self.starts("false") && !self.at(5).map(is_bare).unwrap_or(false) => {
                self.i += 5;
                Ok(Value::Boolean(false))
            }
            Some(b'[') => self.array(),
            Some(b'{') => self.inline_table(),
            Some(c) if c.is_ascii_digit() || c == b'+' || c == b'-' || c == b'i' || c == b'n' => {
                let save = self.i;
                match self.number_or_date() {
                    Ok(v) => Ok(v),
                    Err(e) => {
                        if c == b'i' || c == b'n' {
                            self.i = save;
                            err(save, "invalid string\nexpected `\"`, `'`")
                        } else {
                            Err(e)
                        }
                    }
                }
            }
            _ => err(self.i, "invalid string\nexpected `\"`, `'`"),
        }
    }
    fn array(&mut self) -> R<Value> {
        self.i += 1;
        let mut items = Vec::new();
        loop {
            self.ws_comment_newline();
            if self.peek() == Some(b']') {
                self.i += 1;
                return Ok(Value::Array(items));
            }
            if self.peek().is_none() {
                return err(self.i, "invalid array\nexpected `]`");
            }
            let v = self.value()?;
            items.push(v);
            self.ws_comment_newline();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b']') => {
                    self.i += 1;
                    return Ok(Value::Array(items));
                }
                _ => return err(self.i, "invalid array\nexpected `]`"),
            }
        }
    }
    fn inline_table(&mut self) -> R<Value> {
        self.i += 1;
        let mut tbl: Vec<(String, Value)> = Vec::new();
        self.ws();
        if self.peek() == Some(b'}') {
            self.i += 1;
            return Ok(Value::Table(tbl));
        }
        loop {
            self.ws();
            let (keys, kpos) = self.key()?;
            self.ws();
            if self.peek() != Some(b'=') {
                return err(self.i, "expected `.`, `=`");
            }
            self.i += 1;
            self.ws();
            let v = self.value()?;
            insert_dotted(&mut tbl, &keys, v, kpos, "inline table")?;
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    return Ok(Value::Table(tbl));
                }
                _ => return err(self.i, "invalid inline table\nexpected `}`"),
            }
        }
    }
}

fn get_table_mut<'t>(tbl: &'t mut Vec<(String, Value)>, key: &str) -> Option<&'t mut Value> {
    tbl.iter_mut().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn insert_dotted(tbl: &mut Vec<(String, Value)>, keys: &[String], v: Value, pos: usize, ctx: &str) -> R<()> {
    let mut cur = tbl;
    for k in &keys[..keys.len() - 1] {
        if get_table_mut(cur, k).is_none() {
            cur.push((k.clone(), Value::Table(Vec::new())));
        }
        match get_table_mut(cur, k).unwrap() {
            Value::Table(t) => cur = t,
            _ => return err(pos, &format!("duplicate key `{}` in {}", k, ctx)),
        }
    }
    let last = &keys[keys.len() - 1];
    if get_table_mut(cur, last).is_some() {
        return err(pos, &format!("duplicate key `{}` in {}", last, ctx));
    }
    cur.push((last.clone(), v));
    Ok(())
}

fn navigate<'t>(root: &'t mut Vec<(String, Value)>, path: &[String]) -> Option<&'t mut Vec<(String, Value)>> {
    let mut cur = root;
    for k in path {
        match get_table_mut(cur, k)? {
            Value::Table(t) => cur = t,
            Value::Array(a) => match a.last_mut() {
                Some(Value::Table(t)) => cur = t,
                _ => return None,
            },
            _ => return None,
        }
    }
    Some(cur)
}

pub fn parse(src: &str) -> Result<Vec<(String, Value)>, TomlError> {
    let mut p = P { s: src.as_bytes(), src, i: 0 };
    let mut root: Vec<(String, Value)> = Vec::new();
    let mut cur_path: Vec<String> = Vec::new();
    let mut defined: Vec<Vec<String>> = Vec::new();
    // skip BOM
    if p.starts("\u{feff}") {
        p.i += 3;
    }
    loop {
        p.ws();
        let c = match p.peek() {
            None => break,
            Some(c) => c,
        };
        if c == b'#' {
            p.comment();
        } else if c == b'\n' || c == b'\r' {
            if !p.newline() {
                return err(p.i, "invalid key");
            }
            continue;
        } else if c == b'[' {
            let array = p.at(1) == Some(b'[');
            let hstart = p.i;
            p.i += if array { 2 } else { 1 };
            p.ws();
            let (keys, _) = match p.key() {
                Ok(k) => k,
                Err(e) => {
                    return Err(TomlError { pos: e.pos, message: format!("invalid table header\n{}", e.message) })
                }
            };
            p.ws();
            if array {
                if !p.starts("]]") {
                    return err(p.i, "invalid table header\nexpected `.`, `]]`");
                }
                p.i += 2;
            } else {
                if p.peek() != Some(b']') {
                    return err(p.i, "invalid table header\nexpected `.`, `]`");
                }
                p.i += 1;
            }
            // create
            let parent_path = &keys[..keys.len() - 1];
            let lastk = keys[keys.len() - 1].clone();
            {
                let mut cur = &mut root;
                for k in parent_path {
                    if get_table_mut(cur, k).is_none() {
                        cur.push((k.clone(), Value::Table(Vec::new())));
                    }
                    cur = match get_table_mut(cur, k).unwrap() {
                        Value::Table(t) => t,
                        Value::Array(a) => match a.last_mut() {
                            Some(Value::Table(t)) => t,
                            _ => return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", k)),
                        },
                        _ => return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", k)),
                    };
                }
                if array {
                    match get_table_mut(cur, &lastk) {
                        None => cur.push((lastk.clone(), Value::Array(vec![Value::Table(Vec::new())]))),
                        Some(Value::Array(a)) => a.push(Value::Table(Vec::new())),
                        Some(_) => {
                            return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk))
                        }
                    }
                } else {
                    if defined.iter().any(|d| d == &keys) {
                        return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk));
                    }
                    match get_table_mut(cur, &lastk) {
                        None => cur.push((lastk.clone(), Value::Table(Vec::new()))),
                        Some(Value::Table(_)) => {}
                        Some(_) => {
                            return err(hstart, &format!("invalid table header\nduplicate key `{}` in document root", lastk))
                        }
                    }
                    defined.push(keys.clone());
                }
            }
            cur_path = keys;
        } else {
            let (keys, kpos) = p.key()?;
            p.ws();
            if p.peek() != Some(b'=') {
                return err(p.i, "expected `.`, `=`");
            }
            p.i += 1;
            p.ws();
            let v = p.value()?;
            let ctx = if cur_path.is_empty() {
                "document root".to_string()
            } else {
                format!("table `{}`", cur_path.join("."))
            };
            let tbl = match navigate(&mut root, &cur_path) {
                Some(t) => t,
                None => return err(kpos, "invalid key"),
            };
            insert_dotted(tbl, &keys, v, kpos, &ctx)?;
        }
        p.ws();
        p.comment();
        if p.peek().is_none() {
            break;
        }
        if !p.newline() {
            return err(p.i, "expected newline, `#`");
        }
    }
    Ok(root)
}
