            let mut m = HashMap::new();
            for (k, v) in t {
                let mut cs = k.chars();
                let c = cs.next()?;
                if cs.next().is_some() {
                    return None;
                }
                m.insert(c, to_string(v)?);
            }
            Some(m)
        }
        _ => None,
    }
}

