// Multi-line text editor state.

pub struct Editor {
    pub lines: Vec<String>,
    pub row: usize,
    pub col: usize, // char index
}

fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn byte_idx(s: &str, ci: usize) -> usize {
    s.char_indices().nth(ci).map(|(i, _)| i).unwrap_or(s.len())
}

impl Editor {
    pub fn new() -> Editor {
        Editor { lines: vec![String::new()], row: 0, col: 0 }
    }
    pub fn content_str(&self) -> String {
        self.lines.join("\n")
    }
    pub fn content_lines(&self) -> &Vec<String> {
        &self.lines
    }
    pub fn set_content(&mut self, text: &str) {
        let mut lines: Vec<String> = text.lines().map(|s| s.to_string()).collect();
        if lines.is_empty() {
            lines.push(String::new());
        }
        self.lines = lines;
        self.row = self.lines.len() - 1;
        self.col = char_len(&self.lines[self.row]);
    }
    pub fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.row = 0;
        self.col = 0;
    }
    pub fn cur_line(&self) -> &String {
        &self.lines[self.row]
    }
    pub fn insert_char(&mut self, c: char) {
        if c == '\n' {
            self.newline();
            return;
        }
        let row = self.row;
        let bi = byte_idx(&self.lines[row], self.col);
        self.lines[row].insert(bi, c);
        self.col += 1;
    }
    pub fn insert_str(&mut self, s: &str) {
        for c in s.chars() {
            self.insert_char(c);
        }
    }
    pub fn newline(&mut self) {
        let row = self.row;
        let bi = byte_idx(&self.lines[row], self.col);
        let rest = self.lines[row].split_off(bi);
        self.lines.insert(row + 1, rest);
        self.row += 1;
        self.col = 0;
    }
    /// returns true if content changed
    pub fn backspace(&mut self) -> bool {
        if self.col > 0 {
            let row = self.row;
            let bi = byte_idx(&self.lines[row], self.col - 1);
            self.lines[row].remove(bi);
            self.col -= 1;
            true
        } else if self.row > 0 {
            let cur = self.lines.remove(self.row);
            self.row -= 1;
            self.col = char_len(&self.lines[self.row]);
            self.lines[self.row].push_str(&cur);
            true
        } else {
            false
