    pub fn delete_word(&mut self) -> bool {
        let row = self.row;
        let chars: Vec<char> = self.lines[row].chars().collect();
        if chars.is_empty() {
            return false;
        }
        if self.col == 0 {
            let bi = byte_idx(&self.lines[row], 0);
            self.lines[row].remove(bi);
            return true;
