fn build_command(env: &ExecEnv, cmd: &str) -> Option<Command> {
    if env.eval_environment.is_empty() {
        return None;
    }
    let mut c;
    if env.isolation {
        c = Command::new("bwrap");
        c.args(BWRAP_ARGS);
        c.args(&env.eval_environment);
    } else {
        c = Command::new(&env.eval_environment[0]);
        c.args(&env.eval_environment[1..]);
    }
    c.arg(cmd);
    c.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    Some(c)
}

fn read_all_string<R: Read>(r: Option<R>) -> String {
    match r {
        None => String::new(),
        Some(mut r) => {
            let mut s = String::new();
            match r.read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => e.to_string(),
            }
        }
    }
}

pub enum RunResult {
    Done { code: Option<i32>, success: bool, stdout: String, stderr: String },
    TimedOut,
    Cancelled,
    SpawnFailed,
    EmptyShell,
}

pub fn run(env: &ExecEnv, cmd: &str, stdin: Option<&str>, timeout: Option<Duration>, cancel: Option<&AtomicBool>) -> RunResult {
    let mut command = match build_command(env, cmd) {
        Some(c) => c,
        None => return RunResult::EmptyShell,
    };
    let mut child = match command.spawn() {
        Ok(c) => c,
        Err(_) => return RunResult::SpawnFailed,
    };
    if let Some(mut si) = child.stdin.take() {
        if let Some(input) = stdin {
            let _ = si.write_all(input.as_bytes());
        }
        drop(si);
    }
    let start = Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(st)) => break st,
            Ok(None) => {}
            Err(_) => {
                let _ = child.kill();
                return RunResult::SpawnFailed;
            }
        }
        if let Some(c) = cancel {
            if c.load(Ordering::SeqCst) {
                let _ = child.kill();
                let _ = child.wait();
                return RunResult::Cancelled;
            }
        }
        if let Some(t) = timeout {
            if start.elapsed() >= t {
                let _ = child.kill();
                let _ = child.wait();
                return RunResult::TimedOut;
            }
        }
        std::thread::sleep(Duration::from_millis(2));
    };
    let stdout = read_all_string(child.stdout.take());
    let stderr = read_all_string(child.stderr.take());
    RunResult::Done { code: status.code(), success: status.success(), stdout, stderr }
}

pub struct Evaluator {
    pub env: ExecEnv,
    next_id: u64,
    current_cancel: Option<Arc<AtomicBool>>,
    tx: Sender<EvalResult>,
    wake_fd: i32,
}

impl Evaluator {
    pub fn new(env: ExecEnv, tx: Sender<EvalResult>, wake_fd: i32) -> Evaluator {
        Evaluator { env, next_id: 0, current_cancel: None, tx, wake_fd }
    }
    pub fn start(&mut self, cmd: String, cmd_raw: String, stdin: Option<String>) -> u64 {
        if let Some(c) = self.current_cancel.take() {
            c.store(true, Ordering::SeqCst);
        }
        self.next_id += 1;
        let id = self.next_id;
        let cancel = Arc::new(AtomicBool::new(false));
        self.current_cancel = Some(cancel.clone());
        let env = self.env.clone();
        let tx = self.tx.clone();
        let wake = self.wake_fd;
        std::thread::spawn(move || {
            let r = run(&env, &cmd, stdin.as_deref(), Some(env.timeout), Some(&cancel));
            let outcome = match r {
                RunResult::Cancelled => return,
                RunResult::Done { success, stdout, stderr, .. } => {
                    if success {
                        Outcome::Success(stdout)
                    } else {
                        Outcome::Failure(stderr)
                    }
                }
                RunResult::TimedOut => Outcome::Failure("Command timed out".to_string()),
                RunResult::SpawnFailed => Outcome::Failure("Unable to spawn command".to_string()),
                RunResult::EmptyShell => Outcome::Failure("shell_command is empty".to_string()),
            };
            let _ = tx.send(EvalResult { id, cmd_raw, outcome });
            crate::term::write_fd(wake, b"x");
        });
        id
    }
}
