#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ListKind {
    History,
    Bookmarks,
}

pub struct CmdListState {
    pub kind: ListKind,
    pub list: Vec<String>,
    pub selected: Option<usize>,
}

pub enum Mode {
    Main,
    Help,
    CmdList(CmdListState),
}

#[derive(Clone)]
pub enum PopupKind {
    Snippets(Vec<(char, Snippet)>),
    HelpViewer(Vec<(char, String)>),
    OutputViewer(Vec<(char, String)>),
}

pub struct CachedPart {
    pub row: usize,
    pub col: usize, // char index of the '|'
    pub prev_lines: Vec<String>,
    pub line_prefix: String, // lines[row][..=col] (bytes)
    pub output: String,
}

pub struct Terminal {
    pub out: Out,
    prev: Buffer,
    cur: Buffer,
    last_area: Rect,
}

impl Terminal {
    pub fn new(out: Out) -> Terminal {
        let (w, h) = term::terminal_size();
        let area = Rect { x: 0, y: 0, width: w, height: h };
        Terminal { out, prev: Buffer::empty(area), cur: Buffer::empty(area), last_area: area }
    }
    pub fn clear(&mut self) {
        self.out.write_str("\x1b[2J");
        self.prev.reset();
    }
    pub fn draw<F: FnOnce(&mut Buffer) -> Option<(u16, u16)>>(&mut self, f: F) {
        let (w, h) = term::terminal_size();
        let area = Rect { x: 0, y: 0, width: w, height: h };
        if area != self.last_area {
            self.prev.resize(area);
            self.cur.resize(area);
            self.clear();
            self.last_area = area;
        }
        let cursor = f(&mut self.cur);
        let updates = self.prev.diff(&self.cur);
        let mut s = crate::buffer::render_updates(&updates);
        match cursor {
            None => s.push_str("\x1b[?25l"),
            Some((x, y)) => {
                s.push_str("\x1b[?25h");
                s.push_str(&format!("\x1b[{};{}H", y as u32 + 1, x as u32 + 1));
            }
        }
        std::mem::swap(&mut self.prev, &mut self.cur);
        self.cur.reset();
        self.out.write_str(&s);
    }
}

