    pub last_executed: String,
    pub output: String,
    pub error: Option<String>,
    pub running: bool,
    pub latest_id: u64,
    pub cached: Option<CachedPart>,
    pub should_quit: bool,
    evaluator: Evaluator,
    results: Receiver<EvalResult>,
    pub wake_read: i32,
    start: Instant,
}

fn history_path() -> std::path::PathBuf {
    crate::pipr_config::pipr_dir().join("history")
}

fn bookmarks_path() -> std::path::PathBuf {
    crate::pipr_config::pipr_dir().join("bookmarks")
}

fn load_entries(p: &std::path::Path) -> Vec<String> {
    match std::fs::read_to_string(p) {
        Ok(s) => s.split("\n---\n").filter(|x| !x.trim().is_empty()).map(|x| x.to_string()).collect(),
        Err(_) => Vec::new(),
    }
}

fn save_entries(p: &std::path::Path, entries: &[String]) {
    let _ = std::fs::create_dir_all(crate::pipr_config::pipr_dir());
    let _ = std::fs::write(p, entries.join("\n---\n"));
}

fn round_half(n: u16) -> u16 {
    ((n as u32 + 1) / 2) as u16
}

fn round_40(n: u16) -> u16 {
    ((n as u32 * 4 + 5) / 10) as u16
}

impl App {
    pub fn new(config: PiprConfig, isolation: bool, raw_mode: bool, initial: &str) -> App {
        let (tx, rx) = channel();
        let (wr, ww) = term::make_pipe();
        let env = ExecEnv {
            eval_environment: config.eval_environment.clone(),
            isolation,
            timeout: config.cmd_timeout,
        };
        let mut editor = Editor::new();
        editor.set_content(initial);
        App {
            autoeval: config.autoeval_mode_default,
            paranoid: config.paranoid_history_mode_default,
            config,
            raw_mode,
            editor,
            history: load_entries(&history_path()),
            history_idx: None,
            bookmarks: load_entries(&bookmarks_path()),
            mode: Mode::Main,
            popup: None,
            last_executed: String::new(),
            output: String::new(),
            error: None,
            running: false,
            latest_id: 0,
            cached: None,
            should_quit: false,
            evaluator: Evaluator::new(env, tx, ww),
            results: rx,
            wake_read: wr,
            start: Instant::now(),
        }
    }

    // ---------------- history / bookmarks ----------------
    pub fn add_to_history(&mut self, cmd: &str) {
        if cmd.is_empty() {
            return;
        }
        if self.history.last().map(|l| l == cmd).unwrap_or(false) {
            return;
        }
        self.history.push(cmd.to_string());
        let size = self.config.history_size;
        if self.history.len() > size {
            let extra = self.history.len() - size;
            self.history.drain(0..extra);
        }
        save_entries(&history_path(), &self.history);
    }

    fn toggle_bookmark(&mut self) {
        let cmd = self.editor.content_str();
        if cmd.is_empty() {
            return;
        }
        if let Some(pos) = self.bookmarks.iter().position(|b| *b == cmd) {
            self.bookmarks.remove(pos);
        } else {
            self.bookmarks.push(cmd);
        }
        save_entries(&bookmarks_path(), &self.bookmarks);
    }

    fn history_prev(&mut self) {
        if self.history.is_empty() {
            return;
        }
        match self.history_idx {
            None => {
                let cur = self.editor.content_str();
                let idx = self.history.len() - 1;
                self.history_idx = Some(idx);
                let entry = self.history[idx].clone();
                self.load_command(&entry);
                self.add_to_history(&cur);
            }
            Some(i) => {
                let idx = i.saturating_sub(1);
                self.history_idx = Some(idx);
                if let Some(entry) = self.history.get(idx).cloned() {
                    self.load_command(&entry);
                }
            }
        }
    }

    fn history_next(&mut self) {
        if let Some(i) = self.history_idx {
            if i + 2 >= self.history.len() {
                self.history_idx = None;
                self.load_command("");
            } else {
                self.history_idx = Some(i + 1);
                let entry = self.history[i + 1].clone();
                self.load_command(&entry);
            }
        }
    }

    fn load_command(&mut self, cmd: &str) {
        self.editor.set_content(cmd);
        self.cached = None;
    }

    // ---------------- evaluation ----------------
    fn processed_command(lines: &[String]) -> String {
        lines.iter().filter(|l| !l.starts_with('#')).cloned().collect::<Vec<_>>().join(" ")
    }

    pub fn execute(&mut self) {
        let raw = self.editor.content_str();
        self.last_executed = raw.clone();
        let lines = self.editor.lines.clone();
        let (cmd, stdin) = match &self.cached {
            Some(c) => {
                let line = &lines[c.row.min(lines.len() - 1)];
                let rest_first: String = line.chars().skip(c.col + 1).collect();
                let mut rest = vec![rest_first];
                rest.extend(lines.iter().skip(c.row + 1).cloned());
                (Self::processed_command(&rest), Some(c.output.clone()))
            }
            None => (Self::processed_command(&lines), None),
        };
        self.latest_id = self.evaluator.start(cmd, raw, stdin);
        self.running = true;
    }

    fn on_edit(&mut self, changed: bool) {
        if !changed {
            return;
        }
        self.history_idx = None;
        self.check_cache();
        if self.autoeval {
            self.execute();
        }
    }

    fn check_cache(&mut self) {
        let valid = match &self.cached {
            None => return,
            Some(c) => {
                let lines = &self.editor.lines;
                if c.row == lines.len().wrapping_sub(1) || (lines.len() == 1 && c.row == 0) {
                    let line = &lines[c.row];
                    let end = c.line_prefix.len();
                    line.get(..end).map(|p| p == c.line_prefix).unwrap_or(false) && lines[..c.row] == c.prev_lines[..]
                } else {
                    if c.row >= lines.len() {
                        crate::util::tui_panic(
                            "src/util.rs:90:25",
                            &format!("index out of bounds: the len is {} but the index is {}", lines.len(), c.row),
                        );
                    }
                    let line = &lines[c.row];
                    let end = c.line_prefix.len();
                    if end > line.len() || !line.is_char_boundary(end) {
                        crate::util::tui_panic("src/util.rs:90:38", &crate::util::slice_end_error(line, end));
                    }
                    &line[..end] == c.line_prefix && lines[..c.row] == c.prev_lines[..]
                }
            }
        };
        if !valid {
            self.cached = None;
        }
    }

    fn cache_at_cursor(&mut self) {
        if self.editor.char_at_cursor() != Some('|') {
            return;
        }
        let row = self.editor.row;
        let col = self.editor.col;
        let lines = self.editor.lines.clone();
        let mut parts: Vec<String> = lines[..row].to_vec();
        parts.push(lines[row].chars().take(col).collect());
        let prefix_cmd = parts.join(" ");
        let r = exec::run(&self.evaluator.env, &prefix_cmd, None, None, None);
        match r {
            RunResult::Done { code, success, stdout, .. } => {
                if success {
                    let line_prefix: String = lines[row].chars().take(col + 1).collect();
                    self.cached = Some(CachedPart {
                        row,
                        col,
                        prev_lines: lines[..row].to_vec(),
                        line_prefix,
                        output: stdout,
                    });
                    if self.autoeval {
                        self.execute();
                    }
                } else {
                    self.error = Some(format!(
                        "could not run command to cache: Non-zero exit code: {}",
                        code.unwrap_or(-1)
                    ));
                }
            }
            RunResult::SpawnFailed => {
                self.error = Some("could not run command to cache: Unable to spawn command".to_string());
            }
            RunResult::EmptyShell => {
                self.error = Some("could not run command to cache: shell_command is empty".to_string());
            }
            _ => {}
        }
    }

    pub fn process_results(&mut self) {
        while let Ok(r) = self.results.try_recv() {
            if r.id == self.latest_id {
                self.running = false;
            }
            match r.outcome {
                Outcome::Success(out) => {
                    self.output = out;
                    self.error = None;
                    if self.paranoid && self.autoeval {
                        let c = r.cmd_raw.clone();
                        self.add_to_history(&c);
                    }
                }
                Outcome::Failure(err) => {
                    self.error = Some(err);
                }
            }
        }
    }

    // ---------------- key handling ----------------
    pub fn handle_key(&mut self, term: &mut Terminal, ev: KeyEvent) {
        let ctrl = ev.mods & MOD_CONTROL != 0;
        match ev.key {
            Key::F(1) => {
                self.mode = match self.mode {
                    Mode::Help => Mode::Main,
                    _ => Mode::Help,
                };
                return;
            }
            Key::F(4) => {
                if let Mode::CmdList(CmdListState { kind: ListKind::History, .. }) = self.mode {
                    self.mode = Mode::Main;
                } else {
                    self.open_list(ListKind::History);
                }
                return;
            }
            Key::Char('b') if ctrl => {
                if let Mode::CmdList(CmdListState { kind: ListKind::Bookmarks, .. }) = self.mode {
                    self.mode = Mode::Main;
                } else {
                    self.open_list(ListKind::Bookmarks);
                }
                return;
            }
            _ => {}
        }
        match self.mode {
            Mode::Help => {
                self.mode = Mode::Main;
            }
            Mode::CmdList(_) => self.handle_list_key(ev),
            Mode::Main => {
                if self.popup.is_some() {
                    self.handle_popup_key(term, ev);
                } else {
                    self.handle_main_key(ev);
                }
            }
        }
    }

    fn open_list(&mut self, kind: ListKind) {
        let cur = self.editor.content_str();
        self.add_to_history(&cur);
        self.popup = None;
        let list = match kind {
            ListKind::History => self.history.clone(),
            ListKind::Bookmarks => self.bookmarks.clone(),
        };
        let selected = if list.is_empty() { None } else { Some(list.len() - 1) };
        self.mode = Mode::CmdList(CmdListState { kind, list, selected });
    }

    fn apply_list(&mut self, kind: ListKind, list: Vec<String>) {
        match kind {
            ListKind::History => {
                self.history = list;
                save_entries(&history_path(), &self.history);
            }
            ListKind::Bookmarks => {
                self.bookmarks = list;
                save_entries(&bookmarks_path(), &self.bookmarks);
            }
        }
    }

    fn handle_list_key(&mut self, ev: KeyEvent) {
        let st = match &mut self.mode {
            Mode::CmdList(s) => s,
            _ => return,
        };
        match ev.key {
            Key::Up => {
                if let Some(s) = st.selected {
                    st.selected = Some(s.saturating_sub(1));
                }
            }
            Key::Down => {
                if let Some(s) = st.selected {
                    if s + 1 < st.list.len() {
                        st.selected = Some(s + 1);
                    }
                }
            }
            Key::Delete | Key::Backspace => {
                if let Some(s) = st.selected {
                    if s < st.list.len() {
                        st.list.remove(s);
                    }
                    if st.list.is_empty() {
                        st.selected = None;
                    }
                }
            }
            Key::Enter => {
                let kind = st.kind;
                let list = std::mem::take(&mut st.list);
                let sel = st.selected.and_then(|s| list.get(s).cloned());
                self.mode = Mode::Main;
                if let Some(cmd) = sel {
                    self.load_command(&cmd);
                    self.history_idx = None;
                }
                self.apply_list(kind, list);
            }
            Key::Esc => {
                let kind = st.kind;
                let list = std::mem::take(&mut st.list);
                self.mode = Mode::Main;
                self.apply_list(kind, list);
            }
            _ => {}
        }
    }

    fn handle_popup_key(&mut self, term: &mut Terminal, ev: KeyEvent) {
        let popup = self.popup.take().unwrap();
        let c = match ev.key {
            Key::Char(c) => c,
            _ => return,
        };
        match popup {
            PopupKind::Snippets(entries) => {
                if let Some((_, sn)) = entries.iter().find(|(k, _)| *k == c) {
                    self.insert_snippet(&sn.clone());
                }
            }
            PopupKind::HelpViewer(entries) => {
                if let Some((_, v)) = entries.iter().find(|(k, _)| *k == c) {
                    let word = self.editor.word_under_cursor();
                    let cmd = v.replace("??", &word);
                    self.run_help_viewer(term, &cmd);
                }
            }
            PopupKind::OutputViewer(entries) => {
                if let Some((_, v)) = entries.iter().find(|(k, _)| *k == c) {
                    let v = v.clone();
                    self.run_output_viewer(term, &v);
                }
            }
        }
    }

    fn insert_snippet(&mut self, sn: &Snippet) {
        let before: String = sn.text.chars().take(sn.cursor_offset).collect();
        let after: String = sn.text.chars().skip(sn.cursor_offset).collect();
        self.editor.insert_str(&before);
        let (r, c) = (self.editor.row, self.editor.col);
        self.editor.insert_str(&after);
        self.editor.row = r;
        self.editor.col = c;
    }

    fn run_help_viewer(&mut self, term: &mut Terminal, cmd: &str) {
        term.out.write_str("\x1b[?1049l");
        let _ = Command::new("bash").arg("-c").arg(cmd).status();
        term.out.write_str("\x1b[?1049h");
        term.clear();
    }

    fn run_output_viewer(&mut self, term: &mut Terminal, viewer: &str) {
        term.out.write_str("\x1b[?1049l");
        let mut child = match Command::new(viewer).stdin(Stdio::piped()).spawn() {
            Ok(c) => c,
            Err(_) => return,
        };
        if let Some(mut si) = child.stdin.take() {
            if si.write_all(self.output.as_bytes()).is_err() {
                return;
            }
            drop(si);
        }
        if child.wait().is_err() {
            return;
        }
        term.out.write_str("\x1b[?1049h");
        term.clear();
    }

    fn handle_main_key(&mut self, ev: KeyEvent) {
        let ctrl = ev.mods & MOD_CONTROL != 0;
        let alt = ev.mods & MOD_ALT != 0;
        match ev.key {
            Key::Esc => self.should_quit = true,
            Key::Char('q') | Key::Char('c') if ctrl => self.should_quit = true,
            Key::Enter if alt => {
                self.editor.newline();
                self.on_edit(true);
            }
            Key::Enter => {
                let cmd = self.editor.content_str();
                self.add_to_history(&cmd);
                self.execute();
            }
            Key::F(2) => self.autoeval = !self.autoeval,
            Key::F(3) => self.paranoid = !self.paranoid,
            Key::F(5) => {
                let word = self.editor.word_under_cursor();
                if !word.is_empty() {
                    let entries: Vec<(char, String)> =
                        self.config.help_viewers.iter().map(|(k, v)| (*k, v.clone())).collect();
                    self.popup = Some(PopupKind::HelpViewer(entries));
                }
            }
            Key::F(6) => {
                let entries: Vec<(char, String)> =
                    self.config.output_viewers.iter().map(|(k, v)| (*k, v.clone())).collect();
                self.popup = Some(PopupKind::OutputViewer(entries));
            }
            Key::F(7) => self.cache_at_cursor(),
            Key::Char('s') if ctrl => self.toggle_bookmark(),
            Key::Char('u') if ctrl => {
                self.editor.clear();
                self.cached = None;
                self.history_idx = None;
                if self.autoeval {
                    self.execute();
                }
            }
            Key::Char('x') if ctrl => {
                self.editor.clear();
            }
            Key::Char('p') if ctrl => self.history_prev(),
            Key::Char('n') if ctrl => self.history_next(),
            Key::Char('v') if ctrl => {
                let entries: Vec<(char, Snippet)> =
                    self.config.snippets.iter().map(|(k, v)| (*k, v.clone())).collect();
                self.popup = Some(PopupKind::Snippets(entries));
            }
            Key::Char('w') if ctrl => {
                let ch = self.editor.delete_word();
                self.on_edit(ch);
            }
            Key::Char('a') if ctrl => self.editor.home(),
            Key::Char('e') if ctrl => self.editor.end(),
            Key::Home => self.editor.home(),
            Key::End => self.editor.end(),
            Key::Left => self.editor.left(),
            Key::Right => self.editor.right(),
            Key::Up => self.editor.up(),
            Key::Down => self.editor.down(),
            Key::Backspace => {
                let ch = self.editor.backspace();
                self.on_edit(ch);
            }
            Key::Delete => {
                let ch = self.editor.delete();
                self.on_edit(ch);
            }
            Key::Char(c) => {
                self.editor.insert_char(c);
                self.on_edit(true);
            }
            _ => {}
        }
    }

    // ---------------- drawing ----------------
    fn main_rect(size: Rect) -> Rect {
        Rect::new(1, 1, size.width.wrapping_sub(2), size.height.wrapping_sub(2))
    }

    pub fn draw(&mut self, buf: &mut Buffer) -> Option<(u16, u16)> {
        let size = buf.area;
        let r = Self::main_rect(size);
        let mut cursor = None;
        let mut mode = std::mem::replace(&mut self.mode, Mode::Main);
        match &mut mode {
            Mode::Help => self.draw_help(buf, r),
            Mode::CmdList(st) => self.draw_list(buf, r, st),
            Mode::Main => cursor = self.draw_main(buf, r),
        }
        self.mode = mode;
        // help hint
        let hx = r.right().wrapping_sub(11);
        let hy = r.bottom().wrapping_sub(1);
        let harea = Rect::new(hx, hy, 8, 1);
        widgets::render_paragraph(&[Line::raw("Help: F1")], None, harea, buf);
        cursor
    }

    fn draw_help(&self, buf: &mut Buffer, r: Rect) {
        let block = Block::new(Some(Span::styled(" Help ", Style::fg_bg(BLACK, CYAN))));
        widgets::render_paragraph(&widgets::text_raw(HELP_TEXT), Some(&block), r, buf);
    }

    fn draw_list(&self, buf: &mut Buffer, r: Rect, st: &mut CmdListState) {
        let list_h = round_half(r.height);
        let list_area = Rect { height: list_h, ..r };
        let rest = Rect { y: r.y + list_h, height: r.height - list_h, ..r };
        let title = match st.kind {
            ListKind::History => " History ",
            ListKind::Bookmarks => " Bookmarks ",
        };
        let block = Block::new(Some(Span::styled(title, Style::fg_bg(BLACK, CYAN))));
        let items: Vec<Line> =
            st.list.iter().map(|e| Line::raw(e.lines().collect::<Vec<_>>().join(" ↵ "))).collect();
        // ratatui clamps the selection during rendering
        let inner = block.inner(list_area);
        if !list_area.intersection(buf.area).is_empty() && !inner.is_empty() {
            if st.list.is_empty() {
                st.selected = None;
            } else if let Some(s) = st.selected {
                if s >= st.list.len() {
                    st.selected = Some(st.list.len() - 1);
                }
            }
        }
        let hl = Style { add: modifier::ITALIC, ..Default::default() };
        widgets::render_list(&items, &block, list_area, buf, st.selected, Some(">>"), hl);
        if let Some(sel) = st.selected.and_then(|s| st.list.get(s)) {
            if self.config.cmdlist_always_show_preview || sel.lines().count() > 1 {
                let pblock = Block::new(Some(Span::styled(" Preview ", Style::fg(CYAN))));
                widgets::render_paragraph(&widgets::text_raw(sel), Some(&pblock), rest, buf);
            }
        }
    }

    fn command_title(&self) -> String {
        let mut t = String::from(" Command");
        let cmd = self.editor.content_str();
        if self.bookmarks.iter().any(|b| *b == cmd) {
            t.push_str(" [Bookmarked]");
        }
        if self.autoeval {
            t.push_str(" [Autoeval]");
        }
        if self.cached.is_some() {
            t.push_str(" [Caching]");
        }
        if self.autoeval && self.paranoid {
            t.push_str(" [Paranoid]");
        }
        t.push(' ');
        t
    }

    fn draw_main(&self, buf: &mut Buffer, r: Rect) -> Option<(u16, u16)> {
        let mut main = r;
        if let Some(p) = &self.popup {
            let sw = round_40(r.width);
            let side = Rect { width: sw, ..r };
            main = Rect { x: r.x + sw, width: r.width - sw, ..r };
            let items: Vec<Line> = match p {
                PopupKind::Snippets(e) => e.iter().map(|(k, s)| Line::raw(format!("{}: {}", k, s.text))).collect(),
                PopupKind::HelpViewer(e) => {
                    let word = self.editor.word_under_cursor();
                    e.iter().map(|(k, v)| Line::raw(format!("{}: {}", k, v.replace("??", &word)))).collect()
                }
                PopupKind::OutputViewer(e) => e.iter().map(|(k, v)| Line::raw(format!("{}: {}", k, v))).collect(),
            };
            let block = Block::new(Some(Span::styled(" Open in ", Style::fg(CYAN))));
            widgets::render_list(&items, &block, side, buf, None, None, Style::default());
        }
        let nlines = self.editor.lines.len();
        let cmd_h = ((nlines + 2).min(u16::MAX as usize) as u16).min(main.height);
        let cmd_area = Rect { height: cmd_h, ..main };
        let rest = Rect { y: main.y + cmd_h, height: main.height - cmd_h, ..main };
        // command input
        let block = Block::new(Some(Span::styled(self.command_title(), Style::fg_bg(BLACK, CYAN))));
        let inner = block.inner(cmd_area);
        let width = inner.width as usize;
        let shown: Vec<String> = self
            .editor
            .lines
            .iter()
            .map(|l| {
                let lim = width.wrapping_sub(3);
                if l.len() > lim {
                    if !l.is_char_boundary(lim) {
                        crate::util::tui_panic("src/ui/mod.rs:215:14", "assertion failed: self.is_char_boundary(new_len)");
                    }
                    format!("{}...", &l[..lim])
                } else {
                    l.clone()
                }
            })
            .collect();
        let text = if self.config.highlighting_enabled {
            highlight::highlight_lines(&shown)
        } else {
            shown.iter().map(|l| Line::raw(l.clone())).collect()
        };
        widgets::render_paragraph(&text, Some(&block), cmd_area, buf);
        // output
        let dirty = self.editor.content_str() != self.last_executed;
        let mut ot = String::from(" Output");
        if dirty {
            ot.push_str(" [+]");
        }
        if self.running {
            let frame = (self.start.elapsed().as_millis() / 100) as usize % SPINNER.len();
            ot.push(' ');
            ot.push_str(SPINNER[frame]);
        }
        ot.push(' ');
        let oblock = Block::new(Some(Span::styled(ot, Style::fg(CYAN))));
        let out_text = ansi::parse(&self.output);
        if let Some(err) = &self.error {
            let oh = round_half(rest.height);
            let oarea = Rect { height: oh, ..rest };
            let earea = Rect { y: rest.y + oh, height: rest.height - oh, ..rest };
            widgets::render_paragraph(&out_text, Some(&oblock), oarea, buf);
            let eblock = Block::new(Some(Span::styled(" Stderr ", Style::fg(CYAN))));
            widgets::render_paragraph(&ansi::parse(err), Some(&eblock), earea, buf);
        } else {
            widgets::render_paragraph(&out_text, Some(&oblock), rest, buf);
        }
        let row = self.editor.row;
        let prefix = self.editor.line_prefix_chars();
        let cx = cmd_area.x as usize + 1 + unicode::str_width(&prefix);
        let cy = cmd_area.y as usize + 1 + row;
        Some((cx.min(u16::MAX as usize) as u16, cy.min(u16::MAX as usize) as u16))
    }

    pub fn final_command(&self) -> String {
        if self.raw_mode {
            self.editor.lines.join("\n")
        } else {
            self.editor.lines.join(" ")
        }
    }
}
