            }
        }
    }
    println!("{}", final_cmd);
}

fn run_loop(app: &mut app::App, terminal: &mut app::Terminal, in_fd: i32) {
    let mut pending: Vec<u8> = Vec::new();
    loop {
        terminal.draw(|buf| app.draw(buf));
        if app.should_quit {
            break;
        }
        let mut fds = [
            term::PollFd { fd: in_fd, events: term::POLLIN, revents: 0 },
            term::PollFd { fd: app.wake_read, events: term::POLLIN, revents: 0 },
        ];
        let timeout = if pending.is_empty() { 100 } else { 0 };
        let n = term::poll_fds(&mut fds, timeout);
        if n > 0 && fds[1].revents != 0 {
            let mut b = [0u8; 64];
            term::read_fd(app.wake_read, &mut b);
        }
        if n > 0 && fds[0].revents != 0 {
            let mut b = [0u8; 4096];
            let r = term::read_fd(in_fd, &mut b);
            if r > 0 {
                pending.extend_from_slice(&b[..r as usize]);
            }
        }
        // parse events
        let mut events = Vec::new();
        loop {
            if pending.is_empty() {
                break;
            }
            // is more input immediately available?
            let more = {
                let mut f = [term::PollFd { fd: in_fd, events: term::POLLIN, revents: 0 }];
                term::poll_fds(&mut f, 0) > 0
            };
            match term::parse_event(&pending, more) {
                term::Parse::Incomplete => {
                    if more {
                        let mut b = [0u8; 4096];
                        let r = term::read_fd(in_fd, &mut b);
                        if r > 0 {
                            pending.extend_from_slice(&b[..r as usize]);
                            continue;
                        }
                    }
                    // cannot complete: treat leading ESC as Esc key, else drop a byte
                    if pending[0] == 0x1b && pending.len() == 1 {
                        events.push(term::KeyEvent { key: term::Key::Esc, mods: 0 });
                        pending.remove(0);
                    } else {
                        break;
                    }
                }
                term::Parse::Event(ev, n) => {
                    pending.drain(..n.min(pending.len()));
                    if let Some(e) = ev {
                        events.push(e);
                    }
                }
            }
        }
        app.process_results();
        for ev in events {
            app.handle_key(terminal, ev);
            if app.should_quit {
                break;
            }
        }
        app.process_results();
    }
}
