// Bash syntax highlighting emulating syntect's Bash grammar with base16-ocean.dark.
use crate::buffer::{Color, Style};
use crate::widgets::{Line, Span};

pub const FG: Color = Color::Rgb(192, 197, 206);
const CYAN: Color = Color::Rgb(150, 181, 180);
const BLUE: Color = Color::Rgb(143, 161, 179);
const GREEN: Color = Color::Rgb(163, 190, 140);
const ORANGE: Color = Color::Rgb(208, 135, 112);
const RED: Color = Color::Rgb(191, 97, 106);
const COMMENT: Color = Color::Rgb(101, 115, 126);
const PURPLE: Color = Color::Rgb(180, 142, 173);

#[derive(Clone, Copy, PartialEq, Debug)]
enum SubKind {
    Dollar,   // $( )
    Backtick, // ` `
    Paren,    // ( )
    Brace,    // { }
    Proc,     // <( ) >( )
}

#[derive(Clone, PartialEq, Debug)]
enum ArgKind {
    Generic,
    Builtin(String),
    Decl,
    Alias,
    Test(bool),
    Other,
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Last {
    Name,
    Opt,
    Other,
}

#[derive(Clone, PartialEq, Debug)]
enum Frame {
    Cmd,
    Args { kind: ArgKind, opts: bool, last: Last },
    DQ,
    SQ,
    DSQ,
    Sub(SubKind),
    Arith { dollar: bool },
    Bracket, // $[ ]
    Param { stage: u8 },
    AssignVal,
    ArrayVal,
    ForHead { stage: u8 },
    CaseHead,
    CasePat,
    CmdName,
}

pub struct Highlighter {
    stack: Vec<Frame>,
    heredoc: Option<(String, bool)>,
    in_heredoc: Option<(String, bool)>,
}

const BUILTINS: &[&str] = &[
    "bg", "bind", "builtin", "caller", "cd", "command", "disown", "echo", "enable", "eval", "exec", "exit", "fg",
    "getopts", "hash", "help", "jobs", "kill", "let", "logout", "mapfile", "printf", "pwd", "read", "readarray",
    "set", "shift", "shopt", "source", "suspend", "times", "trap", "type", "ulimit", "umask", "unalias", "unset",
    "wait", ":", ".",
];

const DECLS: &[&str] = &["export", "local", "declare", "readonly", "typeset"];

fn is_meta(c: char) -> bool {
    c.is_whitespace() || matches!(c, ';' | '|' | '&' | '(' | ')' | '<' | '>')
}

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}

fn is_ident(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

fn builtin_opt_ok(name: &str, opt: &str) -> bool {
    let b = opt.as_bytes();
    if b.len() < 2 {
        return false;
    }
    let sign = b[0];
    let letters = &opt[1..];
    let all_in = |set: &str| letters.chars().all(|c| set.contains(c)) && !letters.is_empty();
    match name {
        "echo" => sign == b'-' && all_in("neE"),
        "set" => (sign == b'-' || sign == b'+') && (all_in("abefhkmnptuvxBCEHPT") || letters == "o"),
        "read" => sign == b'-' && all_in("adeinNprstu"),
        "cd" => sign == b'-' && all_in("LPe@"),
        "pwd" => sign == b'-' && all_in("LP"),
        "kill" => sign == b'-' && letters.len() == 1 && all_in("snlL"),
        "printf" => sign == b'-' && letters == "v",
        "type" => sign == b'-' && all_in("afptP"),
        "command" => sign == b'-' && all_in("pvV"),
        "unset" => sign == b'-' && all_in("fvn"),
        "ulimit" => sign == b'-' && letters.chars().all(|c| c.is_ascii_alphabetic()),
        "hash" => sign == b'-' && all_in("lrpdt"),
        "disown" => sign == b'-' && all_in("hr"),
        "mapfile" | "readarray" => sign == b'-' && all_in("dnOstuC"),
        "suspend" => sign == b'-' && letters == "f",
        "alias" => sign == b'-' && letters == "p",
        _ => false,
    }
}

struct Out {
    spans: Vec<(String, Color)>,
}

impl Out {
    fn push(&mut self, s: &str, c: Color) {
        if s.is_empty() {
            return;
        }
        if let Some(last) = self.spans.last_mut() {
            if last.1 == c {
                last.0.push_str(s);
                return;
            }
        }
        self.spans.push((s.to_string(), c));
    }
    fn pushc(&mut self, ch: char, c: Color) {
        let mut b = [0u8; 4];
        self.push(ch.encode_utf8(&mut b), c);
    }
}

impl Highlighter {
    pub fn new() -> Highlighter {
        Highlighter { stack: vec![Frame::Cmd], heredoc: None, in_heredoc: None }
    }

    fn base(&self) -> Color {
        let mut c = FG;
        for f in &self.stack {
            match f {
                Frame::DQ | Frame::AssignVal => c = GREEN,
                Frame::CmdName => c = BLUE,
                Frame::Cmd | Frame::Args { .. } => {
                    if c == BLUE {
                        c = FG
                    }
                }
                _ => {}
            }
        }
        c
    }

    fn top(&self) -> Frame {
        self.stack.last().cloned().unwrap_or(Frame::Cmd)
    }

    fn set_top(&mut self, f: Frame) {
        if let Some(t) = self.stack.last_mut() {
            *t = f;
        } else {
            self.stack.push(f);
        }
    }

    /// find nearest enclosing Sub frame kind
    fn enclosing_sub(&self) -> Option<(usize, SubKind)> {
        for (i, f) in self.stack.iter().enumerate().rev() {
            match f {
                Frame::Sub(k) => return Some((i, *k)),
                Frame::DQ | Frame::SQ | Frame::DSQ | Frame::Param { .. } | Frame::Arith { .. } => return None,
                _ => {}
            }
        }
        None
    }

    fn closer_matches(&self, cs: &[char], i: usize) -> Option<(usize, SubKind)> {
        let c = cs[i];
        let (idx, k) = self.enclosing_sub()?;
        let ok = match k {
            SubKind::Dollar | SubKind::Paren | SubKind::Proc => c == ')',
            SubKind::Backtick => c == '`',
            SubKind::Brace => c == '}' && (i == 0 || cs[i - 1].is_whitespace() || cs[i - 1] == ';'),
        };
        if ok {
            Some((idx, k))
        } else {
            None
        }
    }

    fn close_sub(&mut self, out: &mut Out, idx: usize, k: SubKind, ch: char) {
        self.stack.truncate(idx);
        let base = self.base();
        let col = match k {
            SubKind::Proc => FG,
            _ => base,
        };
        out.pushc(ch, col);
        match k {
            SubKind::Paren | SubKind::Brace => {
                // a compound command ended: arguments (redirections etc) may follow
                if matches!(self.top(), Frame::Cmd) {
                    self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                }
            }
            _ => {}
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<(String, Color)> {
        let cs: Vec<char> = line.chars().collect();
        let mut out = Out { spans: Vec::new() };
        // heredoc body
        if let Some((delim, strip)) = self.in_heredoc.clone() {
            let cmp = if strip { line.trim_start_matches('\t') } else { line };
            if cmp == delim {
                out.push(line, PURPLE);
                self.in_heredoc = None;
            } else {
                self.heredoc_body(&cs, &mut out);
            }
            return out.spans;
        }
        let mut i = 0;
        let n = cs.len();
        let mut guard = 0;
        while i < n {
            guard += 1;
            if guard > 100000 {
                break;
            }
            let ni = self.step(&cs, i, &mut out);
            if ni <= i {
                // safety: always progress
                out.pushc(cs[i], self.base());
                i += 1;
            } else {
                i = ni;
            }
        }
        self.end_of_line();
        if let Some(h) = self.heredoc.take() {
            self.in_heredoc = Some(h);
        }
        out.spans
    }

    fn heredoc_body(&mut self, cs: &[char], out: &mut Out) {
        for &c in cs {
            out.pushc(c, GREEN);
        }
    }

    fn end_of_line(&mut self) {
        // newline terminates simple commands, comments etc.
        loop {
            match self.top() {
                Frame::Args { .. } | Frame::AssignVal | Frame::CmdName | Frame::ArrayVal => {
                    self.stack.pop();
                }
                Frame::ForHead { .. } => {
                    self.stack.pop();
                }
                Frame::CaseHead => {
                    self.set_top(Frame::CasePat);
                    break;
                }
                _ => break,
            }
            if self.stack.is_empty() {
                self.stack.push(Frame::Cmd);
                break;
            }
        }
        if self.stack.is_empty() {
            self.stack.push(Frame::Cmd);
        }
    }

    fn step(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        match self.top() {
            Frame::Cmd => self.step_cmd(cs, i, out),
            Frame::CmdName => self.step_cmdname(cs, i, out),
            Frame::Args { .. } => self.step_args(cs, i, out),
            Frame::DQ => self.step_dq(cs, i, out),
            Frame::SQ => {
                if cs[i] == '\'' {
                    out.pushc('\'', FG);
                    self.stack.pop();
                } else {
                    out.pushc(cs[i], GREEN);
                }
                i + 1
            }
            Frame::DSQ => {
                if cs[i] == '\'' {
                    out.pushc('\'', FG);
                    self.stack.pop();
                    i + 1
                } else if cs[i] == '\\' && i + 1 < cs.len() {
                    out.pushc('\\', CYAN);
                    out.pushc(cs[i + 1], CYAN);
                    i + 2
                } else {
                    out.pushc(cs[i], GREEN);
                    i + 1
                }
            }
            Frame::Sub(_) => {
                self.stack.push(Frame::Cmd);
                i
            }
            Frame::Arith { .. } => self.step_arith(cs, i, out),
            Frame::Bracket => {
                if cs[i] == ']' {
                    out.pushc(']', PURPLE);
                    self.stack.pop();
                } else {
                    out.pushc(cs[i], FG);
                }
                i + 1
            }
            Frame::Param { stage } => self.step_param(cs, i, out, stage),
            Frame::AssignVal => self.step_assignval(cs, i, out),
            Frame::ArrayVal => {
                if cs[i] == ')' {
                    out.pushc(')', FG);
                    self.stack.pop();
                } else {
                    out.pushc(cs[i], FG);
                }
                i + 1
            }
            Frame::ForHead { stage } => self.step_forhead(cs, i, out, stage),
            Frame::CaseHead => self.step_casehead(cs, i, out),
            Frame::CasePat => self.step_casepat(cs, i, out),
        }
    }

    fn word_end(cs: &[char], i: usize) -> usize {
        let mut j = i;
        while j < cs.len() && !is_meta(cs[j]) && !matches!(cs[j], '"' | '\'' | '`' | '$' | '\\') {
            j += 1;
        }
        j
    }

    fn keyword_follow_ok(cs: &[char], j: usize) -> bool {
        j < cs.len() && (cs[j].is_whitespace() || matches!(cs[j], ';' | '&' | '|' | '<' | '>' | ')'))
    }

    fn step_cmd(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let c = cs[i];
        let base = self.base();
        if c.is_whitespace() {
            out.pushc(c, base);
            return i + 1;
        }
        if c == '#' {
            let s: String = cs[i..].iter().collect();
            out.push(&s, COMMENT);
            return cs.len();
        }
        if let Some((idx, k)) = self.closer_matches(cs, i) {
            self.close_sub(out, idx, k, c);
            return i + 1;
        }
        // operators at command position
        for op in ["&&", "||", "|&", ";;", "|", ";", "&"] {
            if starts_with(cs, i, op) {
                if op == ";;" && self.in_case() {
                    out.push(op, FG);
                    self.stack.pop();
                    self.set_top_case_pat();
                    return i + 2;
                }
                out.push(op, FG);
                return i + op.chars().count();
            }
        }
        // redirections without command
        if c == '>' || c == '<' {
            self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
            return i;
        }
        if starts_with(cs, i, "[[") && cs.get(i + 2).map(|c| c.is_whitespace()).unwrap_or(false) {
            out.push("[[", CYAN);
            self.stack.push(Frame::Args { kind: ArgKind::Test(true), opts: true, last: Last::Other });
            return i + 2;
        }
        if c == '[' && cs.get(i + 1).map(|c| c.is_whitespace()).unwrap_or(false) {
            out.push("[", CYAN);
            self.stack.push(Frame::Args { kind: ArgKind::Test(false), opts: true, last: Last::Other });
            return i + 1;
        }
        if starts_with(cs, i, "((") {
            out.push("((", base);
            self.stack.push(Frame::Arith { dollar: false });
            return i + 2;
        }
        if c == '(' {
            out.pushc('(', base);
            self.stack.push(Frame::Sub(SubKind::Paren));
            self.stack.push(Frame::Cmd);
            return i + 1;
        }
        if c == '{' && cs.get(i + 1).map(|c| c.is_whitespace()).unwrap_or(false) {
            out.pushc('{', base);
            self.stack.push(Frame::Sub(SubKind::Brace));
            self.stack.push(Frame::Cmd);
            return i + 1;
        }
        // assignment
        if let Some(j) = assignment_eq(cs, i) {
            // name (with optional subscript)
            let mut k = i;
            while k < j {
                let ch = cs[k];
                if ch == '[' {
                    out.pushc('[', RED);
                    k += 1;
                    while k < j && cs[k] != ']' {
                        let col = if cs[k].is_ascii_digit() { ORANGE } else { RED };
                        out.pushc(cs[k], col);
                        k += 1;
                    }
                    if k < j {
                        out.pushc(']', RED);
                        k += 1;
                    }
                    continue;
                }
                if ch == '+' && k + 1 == j {
                    break;
                }
                out.pushc(ch, RED);
                k += 1;
            }
            let opstart = k;
            let op: String = cs[opstart..=j].iter().collect();
            out.push(&op, FG);
            let after = j + 1;
            if cs.get(after) == Some(&'(') {
                out.pushc('(', FG);
                self.stack.push(Frame::ArrayVal);
                return after + 1;
            }
            self.stack.push(Frame::AssignVal);
            return after;
        }
        let we = Self::word_end(cs, i);
        let word: String = cs[i..we].iter().collect();
        if !word.is_empty() && we == cs.len() || (we < cs.len() && is_meta(cs[we])) {
            // plain word: keyword / builtin detection
            let follow = Self::keyword_follow_ok(cs, we);
            let at_eol = we == cs.len();
            if self.in_case_pat_context() && word == "esac" && (follow || at_eol) {
                out.push(&word, PURPLE);
                return we;
            }
            match word.as_str() {
                "if" | "then" | "else" | "elif" | "while" | "until" | "do" | "!" if false => {}
                "then" | "return" if follow || at_eol => {
                    out.push(&word, PURPLE);
                    if word == "return" {
                        self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                    }
                    return we;
                }
                "if" | "else" | "elif" | "while" | "until" | "do" if follow => {
                    out.push(&word, PURPLE);
                    return we;
                }
                "fi" | "done" if follow => {
                    out.push(&word, PURPLE);
                    self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                    return we;
                }
                "break" if follow => {
                    out.push(&word, PURPLE);
                    self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                    return we;
                }
                "continue" if follow => {
                    out.push(&word, PURPLE);
                    return we;
                }
                "for" if follow => {
                    out.push(&word, PURPLE);
                    self.stack.push(Frame::ForHead { stage: 0 });
                    return we;
                }
                "case" if follow => {
                    out.push(&word, PURPLE);
                    self.stack.push(Frame::CaseHead);
                    return we;
                }
                "function" if follow => {
                    out.push(&word, PURPLE);
                    // function name
                    let mut k = we;
                    while k < cs.len() && cs[k].is_whitespace() {
                        out.pushc(cs[k], base);
                        k += 1;
                    }
                    let e = Self::word_end(cs, k);
                    let name: String = cs[k..e].iter().collect();
                    out.push(&name, BLUE);
                    return e;
                }
                _ => {}
            }
            if (follow || at_eol || (we < cs.len() && is_meta(cs[we]))) && BUILTINS.contains(&word.as_str()) {
                out.push(&word, CYAN);
                self.stack.push(Frame::Args { kind: ArgKind::Builtin(word.clone()), opts: true, last: Last::Other });
                return we;
            }
            if follow && DECLS.contains(&word.as_str()) {
                out.push(&word, PURPLE);
                self.stack.push(Frame::Args { kind: ArgKind::Decl, opts: true, last: Last::Other });
                return we;
            }
            if follow && word == "alias" {
                out.push(&word, CYAN);
                self.stack.push(Frame::Args { kind: ArgKind::Alias, opts: true, last: Last::Other });
                return we;
            }
        }
        // generic command name
        self.set_top(Frame::Cmd);
        self.stack.push(Frame::Args { kind: ArgKind::Generic, opts: true, last: Last::Name });
        self.stack.push(Frame::CmdName);
        i
    }

    fn in_case(&self) -> bool {
        self.stack.iter().any(|f| matches!(f, Frame::CasePat))
    }

    fn in_case_pat_context(&self) -> bool {
        // directly inside a case body (statement level)
        let n = self.stack.len();
        n >= 2 && matches!(self.stack[n - 2], Frame::CasePat)
    }

    fn set_top_case_pat(&mut self) {
        // pop until CasePat is on top
        while let Some(f) = self.stack.last() {
            if matches!(f, Frame::CasePat) {
                break;
            }
            self.stack.pop();
        }
        if self.stack.is_empty() {
            self.stack.push(Frame::Cmd);
        }
    }

    fn step_cmdname(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let c = cs[i];
        if is_meta(c) {
            self.stack.pop();
            return i;
        }
        match c {
            '"' => {
                out.pushc('"', FG);
                self.stack.push(Frame::DQ);
                i + 1
            }
            '\'' => {
                out.pushc('\'', FG);
                self.stack.push(Frame::SQ);
                i + 1
            }
            '\\' => {
                if i + 1 < cs.len() {
                    out.pushc('\\', CYAN);
                    out.pushc(cs[i + 1], CYAN);
                    i + 2
                } else {
                    out.pushc('\\', BLUE);
                    i + 1
                }
            }
            '$' => {
                if cs.get(i + 1) == Some(&'(') {
                    out.pushc('$', FG);
                    let mut k = i + 1;
                    let mut depth = 0;
                    while k < cs.len() {
                        if cs[k] == '(' {
                            depth += 1;
                        } else if cs[k] == ')' {
                            depth -= 1;
                            if depth == 0 {
                                out.pushc(')', BLUE);
                                k += 1;
                                break;
                            }
                        }
                        out.pushc(cs[k], BLUE);
                        k += 1;
                    }
                    k
                } else {
                    self.dollar(cs, i, out)
                }
            }
            '`' => {
                out.pushc('`', BLUE);
                self.stack.push(Frame::Sub(SubKind::Backtick));
                i + 1
            }
            _ => {
                out.pushc(c, BLUE);
                i + 1
            }
        }
    }

    fn args_last(&mut self, l: Last) {
        if let Some(Frame::Args { last, .. }) = self.stack.last_mut() {
            *last = l;
        }
    }

    fn step_args(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let (kind, opts, last) = match self.top() {
            Frame::Args { kind, opts, last } => (kind, opts, last),
            _ => unreachable!(),
        };
        let base = self.base();
        let c = cs[i];
        if c.is_whitespace() {
            let mut j = i;
            while j < cs.len() && cs[j].is_whitespace() {
                j += 1;
            }
            let ws: String = cs[i..j].iter().collect();
            if j < cs.len() && cs[j] == '#' {
                let col = match (kind.clone(), last) {
                    (ArgKind::Generic, Last::Name) => BLUE,
                    (ArgKind::Generic, Last::Opt) => RED,
                    _ => base,
                };
                out.push(&ws, col);
                let s: String = cs[j..].iter().collect();
                out.push(&s, COMMENT);
                return cs.len();
            }
            if kind == ArgKind::Generic && opts && j < cs.len() {
                if let Some(e) = generic_option(cs, j) {
                    out.push(&ws, RED);
                    self.emit_option(cs, j, e, out);
                    self.args_last(Last::Opt);
                    return e;
                }
                // "--" ends options
                if starts_with(cs, j, "--") && (j + 2 == cs.len() || cs[j + 2].is_whitespace()) {
                    out.push(&ws, base);
                    out.push("--", base);
                    if let Some(Frame::Args { opts, last, .. }) = self.stack.last_mut() {
                        *opts = false;
                        *last = Last::Other;
                    }
                    return j + 2;
                }
            }
            out.push(&ws, base);
            self.args_last(Last::Other);
            return j;
        }
        if c == '#' && i > 0 && cs[i - 1].is_whitespace() {
            let s: String = cs[i..].iter().collect();
            out.push(&s, COMMENT);
            return cs.len();
        }
        if let Some((idx, k)) = self.closer_matches(cs, i) {
            self.close_sub(out, idx, k, c);
            return i + 1;
        }
        // test closers
        if let ArgKind::Test(double) = kind {
            let at_word_start = i == 0 || cs[i - 1].is_whitespace();
            if at_word_start {
                if double && starts_with(cs, i, "]]") {
                    out.push("]]", CYAN);
                    self.set_top(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                    return i + 2;
                }
                if !double && c == ']' {
                    out.push("]", CYAN);
                    self.set_top(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
                    return i + 1;
                }
                if c == '-' {
                    let mut e = i + 1;
                    while e < cs.len() && cs[e].is_ascii_alphabetic() {
                        e += 1;
                    }
                    if e > i + 1 && (e == cs.len() || cs[e].is_whitespace()) {
                        let s: String = cs[i..e].iter().collect();
                        out.push(&s, RED);
                        return e;
                    }
                }
            }
            if double && (starts_with(cs, i, "&&") || starts_with(cs, i, "||")) {
                out.push(&cs[i..i + 2].iter().collect::<String>(), base);
                return i + 2;
            }
            if c == '<' || c == '>' {
                out.pushc(c, base);
                return i + 1;
            }
        }
        // redirections
        if let Some(r) = self.redirection(cs, i, out) {
            return r;
        }
        // list operators
        for op in ["&&", "||", "|&", ";;", "|", ";", "&"] {
            if starts_with(cs, i, op) {
                if op == ";;" && self.in_case() {
                    out.push(op, FG);
                    self.set_top_case_pat();
                    return i + 2;
                }
                if op == ";;" {
                    out.push(op, FG);
                    self.stack.pop();
                    return i + 2;
                }
                out.push(op, FG);
                self.stack.pop();
                return i + op.chars().count();
            }
        }
        if c == '(' {
            if last == Last::Name && starts_with(cs, i, "()") {
                out.push("()", FG);
                self.stack.pop();
                return i + 2;
            }
            out.pushc('(', base);
            return i + 1;
        }
        if c == ')' {
            out.pushc(')', base);
            return i + 1;
        }
        // word start specific handling
        let at_word_start = i == 0 || cs[i - 1].is_whitespace();
        match kind {
            ArgKind::Builtin(ref name) if at_word_start && (c == '-' || c == '+') => {
                let e = Self::word_end(cs, i);
                let w: String = cs[i..e].iter().collect();
                if (e == cs.len() || is_meta(cs[e])) && builtin_opt_ok(name, &w) {
                    out.push(&w, RED);
                    return e;
                }
                out.push(&w, base);
                return e;
            }
            ArgKind::Decl if at_word_start => {
                if c == '-' || c == '+' {
                    let mut e = i + 1;
                    while e < cs.len() && cs[e].is_ascii_alphabetic() {
                        e += 1;
                    }
                    if e > i + 1 {
                        let s: String = cs[i..e].iter().collect();
                        out.push(&s, RED);
                        return e;
                    }
                }
                if is_ident_start(c) {
                    let mut e = i;
                    while e < cs.len() && is_ident(cs[e]) {
                        e += 1;
                    }
                    let s: String = cs[i..e].iter().collect();
                    out.push(&s, RED);
                    if starts_with(cs, e, "+=") || cs.get(e) == Some(&'=') {
                        let ol = if cs[e] == '+' { 2 } else { 1 };
                        out.push(&cs[e..e + ol].iter().collect::<String>(), FG);
                        let after = e + ol;
                        if cs.get(after) == Some(&'(') {
                            out.pushc('(', FG);
                            self.stack.push(Frame::ArrayVal);
                            return after + 1;
                        }
                        self.stack.push(Frame::AssignVal);
                        return after;
                    }
                    return e;
                }
            }
            ArgKind::Alias if at_word_start => {
                if c == '-' {
                    let e = Self::word_end(cs, i);
                    let w: String = cs[i..e].iter().collect();
                    out.push(&w, if w == "-p" { RED } else { base });
                    return e;
                }
                let mut e = i;
                while e < cs.len() && !is_meta(cs[e]) && cs[e] != '=' && !matches!(cs[e], '"' | '\'' | '$' | '`' | '\\') {
                    e += 1;
                }
                if e > i {
                    let s: String = cs[i..e].iter().collect();
                    out.push(&s, BLUE);
                    if cs.get(e) == Some(&'=') {
                        out.pushc('=', FG);
                        return e + 1;
                    }
                    return e;
                }
            }
            _ => {}
        }
        self.args_last(Last::Other);
        self.word_element(cs, i, out, base, kind == ArgKind::Test(true) || kind == ArgKind::Generic || kind == ArgKind::Other || matches!(kind, ArgKind::Builtin(_)) || kind == ArgKind::Test(false))
    }

    fn emit_option(&mut self, cs: &[char], s: usize, e: usize, out: &mut Out) {
        let mut k = s;
        while k < e {
            if cs[k] == '\\' && k + 1 < e {
                out.pushc('\\', CYAN);
                out.pushc(cs[k + 1], CYAN);
                k += 2;
            } else {
                out.pushc(cs[k], RED);
                k += 1;
            }
        }
    }

    fn redirection(&mut self, cs: &[char], i: usize, out: &mut Out) -> Option<usize> {
        let mut j = i;
        while j < cs.len() && cs[j].is_ascii_digit() {
            j += 1;
        }
        let digits_ok = j == i || (i == 0 || cs[i - 1].is_whitespace() || matches!(cs[i - 1], ';' | '|' | '&'));
        if !digits_ok {
            return None;
        }
        let ops = ["&>>", "&>", "<<<", "<<-", "<<", ">>", ">&", "<&", "<>", ">", "<"];
        let op = ops.iter().find(|o| starts_with(cs, j, o))?;
        if j > i && op.starts_with('&') {
            return None;
        }
        // process substitution
        if j == i && (*op == "<" || *op == ">") && cs.get(j + 1) == Some(&'(') {
            out.pushc(cs[j], FG);
            out.pushc('(', FG);
            self.stack.push(Frame::Sub(SubKind::Proc));
            self.stack.push(Frame::Cmd);
            return Some(j + 2);
        }
        let digits: String = cs[i..j].iter().collect();
        out.push(&digits, ORANGE);
        out.push(op, FG);
        let mut k = j + op.len();
        match *op {
            ">&" | "<&" => {
                let mut e = k;
                while e < cs.len() && cs[e].is_ascii_digit() {
                    e += 1;
                }
                if e > k {
                    out.push(&cs[k..e].iter().collect::<String>(), ORANGE);
                    k = e;
                } else if cs.get(k) == Some(&'-') {
                    out.pushc('-', FG);
                    k += 1;
                }
            }
            "<<" | "<<-" => {
                let base = self.base();
                let mut e = k;
                while e < cs.len() && cs[e].is_whitespace() {
                    e += 1;
                }
                out.push(&cs[k..e].iter().collect::<String>(), if base == FG { GREEN } else { base });
                k = e;
                let (delim, end) = heredoc_delim(cs, k, out);
                if !delim.is_empty() {
                    self.heredoc = Some((delim, *op == "<<-"));
                }
                k = end;
            }
            "<<<" => {
                let base = self.base();
                let mut e = k;
                while e < cs.len() && cs[e].is_whitespace() {
                    out.pushc(cs[e], base);
                    e += 1;
                }
                k = e;
                if k < cs.len() && !matches!(cs[k], '"' | '\'' | '$' | '`') && !is_meta(cs[k]) {
                    let we = Self::word_end(cs, k);
                    out.push(&cs[k..we].iter().collect::<String>(), PURPLE);
                    k = we;
                }
            }
            _ => {}
        }
        Some(k)
    }

    fn word_element(&mut self, cs: &[char], i: usize, out: &mut Out, base: Color, glob: bool) -> usize {
        let c = cs[i];
        match c {
            '"' => {
                out.pushc('"', FG);
                self.stack.push(Frame::DQ);
                i + 1
            }
            '\'' => {
                out.pushc('\'', FG);
                self.stack.push(Frame::SQ);
                i + 1
            }
            '\\' => {
                if i + 1 < cs.len() {
                    out.pushc('\\', CYAN);
                    out.pushc(cs[i + 1], CYAN);
                    i + 2
                } else {
                    out.pushc('\\', base);
                    i + 1
                }
            }
            '$' => self.dollar(cs, i, out),
            '`' => {
                out.pushc('`', base);
                self.stack.push(Frame::Sub(SubKind::Backtick));
                i + 1
            }
            '~' => {
                out.pushc('~', RED);
                i + 1
            }
            '%' => {
                let mut e = i + 1;
                if e < cs.len() && cs[e].is_ascii_digit() {
                    while e < cs.len() && cs[e].is_ascii_digit() {
                        e += 1;
                    }
                    out.pushc('%', base);
                    out.push(&cs[i + 1..e].iter().collect::<String>(), ORANGE);
                    return e;
                }
                if e < cs.len() && is_ident_start(cs[e]) {
                    while e < cs.len() && is_ident(cs[e]) {
                        e += 1;
                    }
                    out.pushc('%', base);
                    out.push(&cs[i + 1..e].iter().collect::<String>(), RED);
                    return e;
                }
                out.pushc('%', base);
                i + 1
            }
            '[' if glob => {
                // glob character class
                let mut e = i + 1;
                while e < cs.len() && cs[e] != ']' && !cs[e].is_whitespace() {
                    e += 1;
                }
                if e < cs.len() && cs[e] == ']' {
                    out.pushc('[', PURPLE);
                    out.push(&cs[i + 1..e].iter().collect::<String>(), base);
                    out.pushc(']', PURPLE);
                    return e + 1;
                }
                out.pushc('[', base);
                i + 1
            }
            _ => {
                out.pushc(c, base);
                i + 1
            }
        }
    }

    fn dollar(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let base = self.base();
        let next = cs.get(i + 1).copied();
        match next {
            Some('(') => {
                if cs.get(i + 2) == Some(&'(') && has_arith_close(cs, i + 3) {
                    out.pushc('$', FG);
                    out.push("((", base);
                    self.stack.push(Frame::Arith { dollar: true });
                    return i + 3;
                }
                out.pushc('$', FG);
                out.pushc('(', base);
                self.stack.push(Frame::Sub(SubKind::Dollar));
                self.stack.push(Frame::Cmd);
                i + 2
            }
            Some('{') => {
                out.pushc('$', FG);
                out.pushc('{', base);
                self.stack.push(Frame::Param { stage: 0 });
                i + 2
            }
            Some('[') => {
                out.pushc('$', FG);
                out.pushc('[', PURPLE);
                self.stack.push(Frame::Bracket);
                i + 2
            }
            Some('\'') if !matches!(self.top(), Frame::DQ) => {
                out.push("$'", FG);
                self.stack.push(Frame::DSQ);
                i + 2
            }
            Some('"') if !matches!(self.top(), Frame::DQ) => {
                out.push("$\"", FG);
                self.stack.push(Frame::DQ);
                i + 2
            }
            Some(c) if is_ident_start(c) => {
                let mut e = i + 1;
                while e < cs.len() && is_ident(cs[e]) {
                    e += 1;
                }
                out.pushc('$', FG);
                out.push(&cs[i + 1..e].iter().collect::<String>(), RED);
                e
            }
            Some(c) if c.is_ascii_digit() || matches!(c, '-' | '*' | '@' | '#' | '?' | '$' | '!' | '_') => {
                out.pushc('$', FG);
                out.pushc(c, RED);
                i + 2
            }
            _ => {
                out.pushc('$', FG);
                i + 1
            }
        }
    }

    fn step_dq(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let c = cs[i];
        match c {
            '"' => {
                out.pushc('"', FG);
                self.stack.pop();
                i + 1
            }
            '\\' => {
                if i + 1 < cs.len() && matches!(cs[i + 1], '$' | '`' | '"' | '\\') {
                    out.pushc('\\', CYAN);
                    out.pushc(cs[i + 1], CYAN);
                    i + 2
                } else {
                    out.pushc('\\', GREEN);
                    i + 1
                }
            }
            '$' => self.dollar(cs, i, out),
            '`' => {
                out.pushc('`', GREEN);
                self.stack.push(Frame::Sub(SubKind::Backtick));
                i + 1
            }
            _ => {
                out.pushc(c, GREEN);
                i + 1
            }
        }
    }

    fn step_arith(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let base = self.base();
        let c = cs[i];
        if starts_with(cs, i, "))") {
            out.push("))", base);
            self.stack.pop();
            if matches!(self.top(), Frame::Cmd) {
                self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
            }
            return i + 2;
        }
        if c.is_ascii_digit() {
            let mut e = i;
            if starts_with(cs, i, "0x") || starts_with(cs, i, "0X") {
                e = i + 2;
                while e < cs.len() && cs[e].is_ascii_hexdigit() {
                    e += 1;
                }
            } else {
                while e < cs.len() && cs[e].is_ascii_alphanumeric() {
                    e += 1;
                }
            }
            out.push(&cs[i..e].iter().collect::<String>(), ORANGE);
            return e;
        }
        if is_ident_start(c) {
            let mut e = i;
            while e < cs.len() && is_ident(cs[e]) {
                e += 1;
            }
            out.push(&cs[i..e].iter().collect::<String>(), base);
            return e;
        }
        if c == '$' {
            return self.dollar(cs, i, out);
        }
        if matches!(c, '+' | '-' | '*' | '/' | '%' | '=' | '<' | '>' | '!' | '&' | '|' | '^' | '~' | '?' | ':' | ',') {
            out.pushc(c, FG);
            return i + 1;
        }
        out.pushc(c, base);
        i + 1
    }

    fn step_param(&mut self, cs: &[char], i: usize, out: &mut Out, stage: u8) -> usize {
        let base = self.base();
        let c = cs[i];
        if c == '}' {
            out.pushc('}', base);
            self.stack.pop();
            return i + 1;
        }
        match stage {
            0 => {
                // prefix
                if c == '#' || c == '!' {
                    out.pushc(c, FG);
                    self.set_top(Frame::Param { stage: 1 });
                    return i + 1;
                }
                self.set_top(Frame::Param { stage: 1 });
                i
            }
            1 => {
                // name
                let mut e = i;
                if c.is_ascii_digit() {
                    while e < cs.len() && cs[e].is_ascii_digit() {
                        e += 1;
                    }
                    out.push(&cs[i..e].iter().collect::<String>(), RED);
                } else if matches!(c, '@' | '*' | '#' | '?' | '$' | '!' | '-') {
                    out.pushc(c, RED);
                    e = i + 1;
                } else {
                    while e < cs.len() && !matches!(cs[e], '}' | ':' | '-' | '=' | '+' | '?' | '#' | '%' | '/' | '^' | ',' | '[') {
                        e += 1;
                    }
                    out.push(&cs[i..e].iter().collect::<String>(), RED);
                }
                if cs.get(e) == Some(&'[') {
                    out.pushc('[', RED);
                    e += 1;
                    while e < cs.len() && cs[e] != ']' && cs[e] != '}' {
                        out.pushc(cs[e], if cs[e].is_ascii_digit() { ORANGE } else { RED });
                        e += 1;
                    }
                    if cs.get(e) == Some(&']') {
                        out.pushc(']', RED);
                        e += 1;
                    }
                }
                self.set_top(Frame::Param { stage: 2 });
                e
            }
            2 => {
                // operator
                let ops = [":-", ":=", ":+", ":?", "##", "%%", "//", "^^", ",,", "-", "=", "+", "?", "#", "%", "/", "^", ",", ":"];
                for op in ops {
                    if starts_with(cs, i, op) {
                        if op == "//" {
                            out.pushc('/', FG);
                            out.pushc('/', RED);
                        } else {
                            out.push(op, FG);
                        }
                        let st = if op == ":" { 4 } else { 3 };
                        self.set_top(Frame::Param { stage: st });
                        return i + op.len();
                    }
                }
                self.set_top(Frame::Param { stage: 3 });
                i
            }
            4 => {
                // substring offsets
                if c.is_ascii_digit() {
                    let mut e = i;
                    while e < cs.len() && cs[e].is_ascii_digit() {
                        e += 1;
                    }
                    out.push(&cs[i..e].iter().collect::<String>(), ORANGE);
                    return e;
                }
                if c == ':' {
                    out.pushc(':', FG);
                    return i + 1;
                }
                self.set_top(Frame::Param { stage: 3 });
                i
            }
            _ => {
                // word part
                match c {
                    '"' | '\'' | '$' | '`' | '\\' => self.word_element(cs, i, out, base, false),
                    _ => {
                        out.pushc(c, base);
                        i + 1
                    }
                }
            }
        }
    }

    fn step_assignval(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let c = cs[i];
        if is_meta(c) {
            self.stack.pop();
            return i;
        }
        if let Some((idx, k)) = self.closer_matches(cs, i) {
            self.close_sub(out, idx, k, c);
            return i + 1;
        }
        self.word_element(cs, i, out, GREEN, false)
    }

    fn step_forhead(&mut self, cs: &[char], i: usize, out: &mut Out, stage: u8) -> usize {
        let base = self.base();
        let c = cs[i];
        if c.is_whitespace() {
            out.pushc(c, base);
            return i + 1;
        }
        if stage == 0 && starts_with(cs, i, "((") {
            out.push("((", base);
            self.stack.pop();
            self.stack.push(Frame::Arith { dollar: false });
            return i + 2;
        }
        if c == ';' {
            out.pushc(';', FG);
            self.stack.pop();
            return i + 1;
        }
        let we = Self::word_end(cs, i);
        let word: String = cs[i..we].iter().collect();
        match stage {
            0 => {
                out.push(&word, base);
                self.set_top(Frame::ForHead { stage: 1 });
                we.max(i + 1)
            }
            1 if word == "in" && Self::keyword_follow_ok(cs, we) => {
                out.push(&word, PURPLE);
                self.set_top(Frame::ForHead { stage: 2 });
                we
            }
            _ => {
                if we > i {
                    out.push(&word, base);
                    we
                } else {
                    self.word_element(cs, i, out, base, true)
                }
            }
        }
    }

    fn step_casehead(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let base = self.base();
        let c = cs[i];
        if c.is_whitespace() {
            out.pushc(c, base);
            return i + 1;
        }
        let we = Self::word_end(cs, i);
        let word: String = cs[i..we].iter().collect();
        if word == "in" && Self::keyword_follow_ok(cs, we) {
            out.push("in", PURPLE);
            self.set_top(Frame::CasePat);
            return we;
        }
        if we > i {
            out.push(&word, base);
            return we;
        }
        self.word_element(cs, i, out, base, false)
    }

    fn step_casepat(&mut self, cs: &[char], i: usize, out: &mut Out) -> usize {
        let base = self.base();
        let c = cs[i];
        if c.is_whitespace() {
            out.pushc(c, base);
            return i + 1;
        }
        let we = Self::word_end(cs, i);
        let word: String = cs[i..we].iter().collect();
        if word == "esac" && (we == cs.len() || Self::keyword_follow_ok(cs, we)) {
            out.push("esac", PURPLE);
            self.stack.pop();
            if self.stack.is_empty() {
                self.stack.push(Frame::Cmd);
            }
            self.stack.push(Frame::Args { kind: ArgKind::Other, opts: false, last: Last::Other });
            return we;
        }
        if c == ')' {
            out.pushc(')', PURPLE);
            self.stack.push(Frame::Cmd);
            return i + 1;
        }
        if c == '(' {
            out.pushc('(', base);
            return i + 1;
        }
        if c == '|' {
            out.pushc('|', base);
            return i + 1;
        }
        if we > i {
            out.push(&word, base);
            return we;
        }
        self.word_element(cs, i, out, base, true)
    }
}

fn starts_with(cs: &[char], i: usize, s: &str) -> bool {
    let mut k = i;
    for c in s.chars() {
        if k >= cs.len() || cs[k] != c {
            return false;
        }
        k += 1;
    }
    true
}

fn has_arith_close(cs: &[char], from: usize) -> bool {
    let mut k = from;
    while k + 1 < cs.len() {
        if cs[k] == ')' && cs[k + 1] == ')' {
            return true;
        }
        k += 1;
    }
    false
}

/// If an assignment starts at i, return the index of the '=' char.
fn assignment_eq(cs: &[char], i: usize) -> Option<usize> {
    let mut k = i;
    let mut in_sub = false;
    while k < cs.len() {
        let c = cs[k];
        if in_sub {
            if c == ']' {
                in_sub = false;
            }
            k += 1;
            continue;
        }
        if c == '=' {
            if k == i {
                return None;
            }
            return Some(k);
        }
        if c == '+' && cs.get(k + 1) == Some(&'=') && k > i {
            return Some(k + 1);
        }
        if c == '[' && k > i {
            in_sub = true;
            k += 1;
            continue;
        }
        if is_meta(c) || matches!(c, '"' | '\'' | '$' | '`' | '\\' | '{' | '}' | '*' | '?' | '[' | ']' | '/' | '~' | '#' | '!' | '@' | '%' | ',' | ':' | '^') {
            return None;
        }
        k += 1;
    }
    None
}

fn generic_option(cs: &[char], j: usize) -> Option<usize> {
    if cs.get(j) != Some(&'-') {
        return None;
    }
    let mut k = j + 1;
    if cs.get(k) == Some(&'-') {
        k += 1;
    }
    match cs.get(k) {
        Some(c) if c.is_ascii_alphanumeric() => {}
        _ => return None,
    }
    while k < cs.len() {
        let c = cs[k];
        if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
            k += 1;
        } else if c == '\\' && k + 1 < cs.len() {
            k += 2;
        } else if c == '~' {
            k += 1;
        } else {
            break;
        }
    }
    Some(k)
}

fn heredoc_delim(cs: &[char], k: usize, out: &mut Out) -> (String, usize) {
    if k >= cs.len() {
        return (String::new(), k);
    }
    let q = cs[k];
    if q == '\'' || q == '"' {
        out.pushc(q, FG);
        let mut e = k + 1;
        while e < cs.len() && cs[e] != q {
            e += 1;
        }
        let d: String = cs[k + 1..e].iter().collect();
        out.push(&d, PURPLE);
        if e < cs.len() {
            out.pushc(q, FG);
            e += 1;
        }
        return (d, e);
    }
    let mut e = k;
    while e < cs.len() && !is_meta(cs[e]) {
        e += 1;
    }
    let d: String = cs[k..e].iter().collect();
    out.push(&d, PURPLE);
    (d, e)
}

pub fn highlight_lines(lines: &[String]) -> Vec<Line> {
    let mut h = Highlighter::new();
    lines
        .iter()
        .map(|l| {
            let spans = h.highlight_line(l);
            Line::from_spans(spans.into_iter().map(|(s, c)| Span::styled(s, Style::fg(c))).collect())
        })
        .collect()
}

/// debugging aid used by the test example
pub fn color_key(c: Color) -> String {
    match c {
        Color::Rgb(r, g, b) => format!("{}/{}/{}", r, g, b),
        _ => String::new(),
    }
}

pub fn runs_for(lines: &[String]) -> Vec<Vec<(String, String)>> {
    let mut h = Highlighter::new();
    lines
        .iter()
        .map(|l| h.highlight_line(l).into_iter().map(|(s, c)| (color_key(c), s)).collect())
        .collect()
}
