use std::io::BufRead;
fn esc(s: &str) -> String {
    let mut o = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o.push('"');
    o
}
fn main() {
    // each input line is a JSON-less test case: lines separated by literal "\n" sequences "⏎"
    let stdin = std::io::stdin();
    let mut first = true;
    println!("{{");
    for l in stdin.lock().lines() {
        let l = l.unwrap();
        if l.is_empty() {
            continue;
        }
        let lines: Vec<String> = l.split('⏎').map(|s| s.to_string()).collect();
        let runs = highlight::runs_for(&lines);
        let mut parts = Vec::new();
        for (li, r) in runs.iter().enumerate() {
            for (k, s) in r {
                let _ = li;
                parts.push(format!("[{}, {}]", esc(k), esc(s)));
            }
        }
        if !first {
            println!(",");
        }
        first = false;
        print!("{}: [{}]", esc(&l), parts.join(", "));
    }
    println!("\n}}");
}
